    ["Right-now sentence"] = "Frase del momento",
    ["Notes for this turn"] = "Note per questo turno",
    ["That prompting option was not found."] = "Quell’opzione di prompt non è stata trovata.",
    ["Keep at least one rule."] = "Mantieni almeno una regola.",
    ["Rule {n} is empty. Write the rule or delete it."] = "La regola {n} è vuota. Scrivi la regola o eliminala.",
    ["Rule {n} is too long. Keep each one under {max} characters."] = "La regola {n} è troppo lunga. Mantieni ciascuna sotto {max} caratteri.",
    ["The rules are too long together. Keep them under {max} characters in all."] = "Le regole sono troppo lunghe nel complesso. Mantienile sotto {max} caratteri in tutto.",
    ["This text is too long. Keep it under {max} characters."] = "Questo testo è troppo lungo. Mantienilo sotto {max} caratteri.",
    ["This text cannot be empty."] = "Questo testo non può essere vuoto.",
    ["Use a number from {min} to {max}."] = "Usa un numero da {min} a {max}.",
    ["Too many stop texts. Keep {max} or fewer."] = "Troppi testi di stop. Mantienine {max} o meno.",
    ["A stop text is too long. Keep each one under {max} characters."] = "Un testo di stop è troppo lungo. Mantieni ciascuno sotto {max} caratteri.",
    ["{field}: {message}"] = "{field}: {message}",
    ["In use now"] = "In uso ora",
    ["How each conversation option is told to answer. Every option has its own prompting. A change counts from the next reply, and nothing needs restarting."] = "Come deve rispondere ogni opzione di conversazione. Ogni opzione ha il proprio prompt. Una modifica vale dalla risposta successiva, senza bisogno di riavviare nulla.",
    ["The facts the characters get from the game and a short list of safety filters cannot be edited here. Convai’s prompting lives on Convai’s side."] = "I fatti che i personaggi ricevono dal gioco e una breve lista di filtri di sicurezza non si possono modificare qui. Il prompt di Convai si trova dalla parte di Convai.",
    ["Mistral and Local AI"] = "Mistral e Local AI",
    ["Lite and Standard are the two Local AI model sizes. “Mature on” is used while Mature content is on."] = "Lite e Standard sono le due dimensioni del modello Local AI. «Maturi attivi» si usa mentre i contenuti maturi sono attivi.",
    ["Your Custom models and APIs"] = "Modelli e API personali",
    ["A Custom model appears here once you choose Custom as the conversation provider and set a model."] = "Un modello personalizzato compare qui quando scegli Personalizzato come provider della conversazione e imposti un modello.",
    ["From {min} to {max}."] = "Da {min} a {max}.",
    ["Shipped: {value}"] = "Originale: {value}",
    ["Rule {n}"] = "Regola {n}",
    ["Rule {n}, for a speaker with a reply length of its own"] = "Regola {n}, per un parlante con una lunghezza di risposta propria",
    ["Rule {n}, for Mature content"] = "Regola {n}, per i contenuti maturi",
    ["Move rule {n} up"] = "Sposta regola {n} su",
    ["Move up"] = "Su",
    ["Move rule {n} down"] = "Sposta la regola {n} giù",
    ["Move down"] = "Giù",
    ["Delete rule {n}"] = "Elimina la regola {n}",
    ["Other versions of this rule"] = "Altre versioni di questa regola",
    ["Leave a version empty to use the rule text."] = "Lascia vuota una versione per usare il testo della regola.",
    ["For a speaker with a reply length of its own"] = "Per un parlante con una lunghezza di risposta propria",
    ["For Mature content"] = "Per i contenuti maturi",
    ["Shipped: off"] = "Originale: no",
    ["Shipped: the mod’s own limit"] = "Originale: il limite proprio del mod",
    ["before V’s words"] = "prima di V",
    ["after V’s words"] = "dopo le parole di V",
    ["Repeat the “where you are” sentence right before V’s words"] = "Ripeti la frase «dove ti trovi» subito prima delle parole di V",
    ["The notes for this turn go"] = "Le note per questo turno vanno",
    ["Output rules"] = "Regole di output",
    ["The numbered rules the model reads before every reply. Use {name} for the character’s name and {words} for the reply length of a speaker that has one."] = "Le regole numerate che il modello legge prima di ogni risposta. Usa {name} per il nome del personaggio e {words} per la lunghezza di risposta di un parlante che ne ha una.",
    ["Example replies"] = "Risposte di esempio",
    ["Replies shown to the model after the rules. A small model may copy them word for word, so add none, or keep them short and plain."] = "Risposte mostrate al modello dopo le regole. Un modello piccolo potrebbe copiarle parola per parola, quindi non aggiungerne nessuna oppure tienile brevi e semplici.",
    ["Add an example reply"] = "Aggiungi un esempio",
    ["An example reply"] = "Risposta d’esempio",
    ["Example reply {n}"] = "Risposta di esempio {n}",
    ["Opening line"] = "Riga di apertura",
    ["The first line of the character text. Use {name} for the character’s name."] = "La prima riga del testo del personaggio. Usa {name} per il nome del personaggio.",
    ["The last thing the model reads before it answers. Use {name} for the character’s name and {words} for the reply length. The Mature setting adds its own clause after it."] = "L’ultima cosa che il modello legge prima di rispondere. Usa {name} per il nome del personaggio e {words} per la lunghezza di risposta. L’impostazione dei contenuti maturi aggiunge la sua frase dopo.",
    ["Section headings"] = "Titoli di sezione",
    ["The headings that mark each part of the prompt. Change the wording, not the order."] = "I titoli che segnano ogni parte del prompt. Cambia la formulazione, non l’ordine.",
    ["Layout"] = "Layout",
    ["Where some notes go in the prompt."] = "Dove vanno alcune note nel prompt.",
    ["Sampling"] = "Campionamento",
    ["How freely the model words its reply. Leave a box empty to use the shipped value."] = "Quanto liberamente il modello formula la sua risposta. Lascia vuota una casella per usare il valore originale.",
    ["Length limits"] = "Limiti lunghezza",
    ["Shorten what the model reads, which makes replies faster. The mod’s own limits still apply, so these can only make things shorter."] = "Accorcia ciò che il modello legge, così le risposte arrivano più in fretta. I limiti propri del mod restano validi, quindi questi possono solo accorciare.",
    ["Stop texts"] = "Testi di stop",
    ["Mature layer"] = "Livello per adulti",
    ["The wording added while Mature content is on. The mod picks the explicit or the suggestive version of a line from what the loaded model allows, so edit the version your model uses. An emptied box leaves that line out. The adults-only line and the hard limits are always added last and cannot be edited."] = "Le formulazioni aggiunte quando i Contenuti per adulti sono attivi. Il mod sceglie la versione esplicita o allusiva di una battuta in base a ciò che consente il modello caricato, quindi modifica la versione che usa il tuo modello. Una casella svuotata toglie quella battuta. La riga solo per adulti e i limiti fissi vengono sempre aggiunti per ultimi e non si possono modificare.",
    ["Speech line"] = "Riga del parlato",
    ["Word bank"] = "Banca di parole",
    ["Romance line"] = "Riga romantica",
    ["Closing clause"] = "Clausola di chiusura",
    ["Tone line"] = "Riga di tono",
    ["Partner paragraph: affection and desire"] = "Paragrafo sul partner: affetto e desiderio",
    ["Partner paragraph: nothing invented"] = "Paragrafo sul partner: niente di inventato",
    ["{part}, for models that allow explicit sex"] = "{part}, per i modelli che consentono il sesso esplicito",
    ["{part}, for models that keep sex suggestive"] = "{part}, per i modelli che mantengono il sesso allusivo",
    ["This option does not get the Mature layer."] = "Questa opzione non riceve il livello per adulti.",
    ["Mature layer and closing line, for models that allow explicit sex"] = "Livello per adulti e riga di chiusura, per i modelli che consentono il sesso esplicito",
    ["Mature layer and closing line, for models that keep sex suggestive"] = "Livello per adulti e riga di chiusura, per i modelli che mantengono il sesso allusivo",
    ["A reply ends when the model writes one of these. Line breaks count. Up to {max}."] = "Una risposta termina quando il modello scrive uno di questi testi. Contano anche gli a capo. Fino a {max}.",
    ["Add a stop text"] = "Aggiungi stop",
    ["A text that ends the reply"] = "Un testo che termina la risposta",
    ["Stop text {n}"] = "Testo di stop {n}",
    ["Preview"] = "Anteprima",
    ["The prompt text as the model would read it for a sample character. It follows your edits as you type, before you save."] = "Il testo del prompt come lo leggerebbe il modello per un personaggio di esempio. Segue le tue modifiche mentre scrivi, prima di salvare.",
    ["Sample character name"] = "Personaggio di esempio",
    ["A speaker with a reply length of its own"] = "Un parlante con una lunghezza di risposta propria",
    ["Reply length in words"] = "Lunghezza in parole",
    ["Mature content is on"] = "Contenuti maturi attivi",
    ["The preview waits until the problems in the form are fixed."] = "L’anteprima attende che i problemi del modulo siano risolti.",
    ["No example replies."] = "Nessun esempio.",
    ["No closing line."] = "Nessuna chiusura.",
    ["Go back to the shipped prompting for {name}? Your changes to this part are removed."] = "Tornare al prompt originale di {name}? Le tue modifiche a questa parte verranno rimosse.",
    ["Go back to the shipped prompting for {name}? All your changes to it are removed."] = "Tornare al prompt originale di {name}? Tutte le tue modifiche verranno rimosse.",
    ["Back to the shipped prompting."] = "Torna al prompt originale.",
    ["Prompting"] = "Prompt",
    ["Street reputation"] = "Reputazione di strada",
    ["Gangs, the NCPD, corporations and the locals of each district remember what V did: Street Cred, choices in jobs, fights, crimes the police saw and how you treat people. It shapes their greeting, trust and help.\n\nOnly ordinary people, never named or story characters. It changes their words, nothing in the game."] = "Gang, NCPD, corporazioni e gente di ogni distretto ricordano cosa ha fatto V: Street Cred, scelte nei lavori, scontri, crimini visti dalla polizia e come tratti le persone. Questo guida saluto, fiducia e aiuto.\n\nSolo persone comuni, mai personaggi con nome o della storia. Cambia le loro parole, nulla nel gioco.",
    ["NPCs react to threats and commands"] = "I PNG reagiscono a minacce e ordini",
    ["Ordinary people you threaten run, cower or fight back, as their kind would: gang members and guards use their fists for an insult and their weapons for a death threat.\n\nThey may also do what you tell them, if they would: get down, stop, or get out of the vehicle.\n\nOnly ordinary people, never named or story characters, and never during scenes, quests or fights."] = "Le persone comuni che minacci scappano, si rannicchiano o reagiscono, secondo la loro natura: membri delle gang e guardie usano i pugni per un insulto e le armi per una minaccia di morte.\n\nPossono anche fare ciò che dici, se lo farebbero: buttarsi a terra, fermarsi o scendere dal veicolo.\n\nSolo persone comuni, mai personaggi con nome o della storia, e mai durante scene, missioni o scontri.",
    ["Voice language"] = "Lingua della voce",
    ["English"] = "inglese",
    ["Automatic"] = "Automatico",
    ["Polish"] = "polacco",
    ["Russian"] = "russo",
    ["Ukrainian"] = "ucraino",
    ["Turkish"] = "turco",
    ["Czech"] = "ceco",
    ["Hungarian"] = "ungherese",
    ["Japanese"] = "giapponese",
    ["Korean"] = "coreano",
    ["Chinese"] = "cinese",
    ["Choose one of the listed reply languages."] = "Scegli una delle lingue di risposta elencate.",
    ["No speech was heard. Hold the talk key while you speak."] = "Nessuna voce rilevata. Tieni premuto il tasto vocale mentre parli.",
    ["Voice activation"] = "Attivazione vocale",
    ["Voice activation could not open the microphone. Check your Windows input device."] = "L'attivazione vocale non è riuscita ad aprire il microfono. Controlla il dispositivo di input di Windows.",
    ["Voice input could not reach Convai. Hold the voice key again, or type."] = "L'input vocale non è riuscito a raggiungere Convai. Tieni di nuovo premuto il tasto vocale oppure scrivi.",
    ["Talk without a key. While you face a character or a companion is near, the mod listens and answers when you pause for about a second.\n\nNever during the game’s own scenes or choices, or while a character speaks. Nothing leaves your PC unless speech is heard. Headphones work best, but a Bluetooth headset’s microphone drops it to call quality while this listens."] = "Parla senza tenere premuto un tasto. Se sei rivolto verso un personaggio o un compagno è vicino, il mod ti ascolta e risponde dopo circa un secondo di pausa.\n\nMai durante le scene o le scelte di dialogo, né mentre un personaggio parla. Nulla lascia il PC finché non si sente parlato. Meglio le cuffie; il microfono Bluetooth passa in qualità di chiamata durante l'ascolto.",
    ["Opening microphone…"] = "Apertura del microfono…",
    ["Speak now"] = "Parla ora",
    ["Type in the search box to find a model by name or record, for example “rita wheeler”. A part of a word is enough."] = "Scrivi nella casella di ricerca per trovare un modello per nome o record, per esempio «rita wheeler». Basta una parte della parola.",
    ["Content packs"] = "Pacchetti di contenuti",
    ["Add-ons that change how the characters talk."] = "Componenti aggiuntivi che cambiano il modo in cui parlano i personaggi.",
    ["Content packs add rules after yours. You cannot edit them here: turn a pack off under Settings > Content packs in the game."] = "I pacchetti di contenuti aggiungono regole dopo le tue. Qui non puoi modificarli: disattiva un pacchetto in Impostazioni > Pacchetti di contenuti nel gioco.",
    ["From the content pack {name}"] = "Dal pacchetto di contenuti {name}",
    ["Content packs that change this prompt: {names}. Your own changes stay on top of theirs, and Reset to default goes back to the pack’s wording."] = "Pacchetti di contenuti che modificano questo prompt: {names}. Le tue modifiche restano sopra le loro, e Ripristina il predefinito torna alla formulazione del pacchetto.",
    ["Memory in use"] = "Memoria in uso",
    ["Normal memory"] = "Memoria normale",
    ["Forget memories clears only the memory shown here. The other memory stays as it is."] = "Dimentica ricordi cancella solo la memoria mostrata qui. L’altra memoria resta com’è.",
    ["This clears the memory in use: {memory}."] = "Questo cancella la memoria in uso: {memory}.",
    ["Backspace"] = "Backspace",
    ["Cancelled."] = "Annullato.",
    ["Caps lock"] = "Blocc Maiusc",
    ["Choose a key or a controller button."] = "Scegli un tasto o un pulsante del controller.",
    ["Choose the keys and controller buttons for talking by voice or text, the group chats and the Companion Manager. They work at once."] = "Scegli i tasti e i pulsanti del controller per parlare a voce o per testo, per le chat di gruppo e per Gestione compagni. Funzionano subito.",
    ["Choose the keys and controller buttons for the mod’s actions. Press Set, then the key or button you want. Esc or B cancels. A change works at once, and the keys you set in Cyber Engine Tweaks keep working. Pick keys the game does not already use."] = "Scegli i tasti e i pulsanti del controller per le azioni della mod. Premi Imposta, poi il tasto o il pulsante che vuoi. Esc o B annulla. Una modifica funziona subito, e i tasti impostati in Cyber Engine Tweaks continuano a funzionare. Scegli tasti che il gioco non usa già.",
    ["Controller {button}"] = "Controller {button}",
    ["D-pad down"] = "Croce direzionale giù",
    ["D-pad left"] = "Croce direzionale sinistra",
    ["D-pad right"] = "Croce direzionale destra",
    ["D-pad up"] = "Croce direzionale su",
    ["Down arrow"] = "Freccia giù",
    ["End"] = "Fine",
    ["Enter"] = "Invio",
    ["Group text chat"] = "Chat di gruppo testuale",
    ["Group voice chat"] = "Chat di gruppo vocale",
    ["Hold it to talk to the characters around you at once, and let go to send. Facing nobody, you talk to the first member of your party and two others from it."] = "Tienilo premuto per parlare a tutti i personaggi intorno a te insieme, e rilascialo per inviare. Se non guardi nessuno, parli con il primo membro del tuo gruppo e con altri due del gruppo.",
    ["Hold it to talk to Johnny, the voice in your head, wherever you face, and let go to send. It needs Johnny in your head turned on in Settings."] = "Tienilo premuto per parlare con Johnny, la voce nella tua testa, ovunque tu guardi, e rilascialo per inviare. Serve che Johnny nella tua testa sia attivato nelle Impostazioni.",
    ["Hold the key or button while you speak and let go to send, like the Cyber Engine Tweaks talk key. Facing nobody, you talk to the first member of your party."] = "Tieni premuto il tasto o il pulsante mentre parli e rilascia per inviare, come il tasto di conversazione di Cyber Engine Tweaks. Se non guardi nessuno, parli con il primo membro del tuo gruppo.",
    ["Home"] = "Home",
    ["Insert"] = "Ins",
    ["Key bindings"] = "Assegnazione tasti",
    ["Key bindings need Codeware, and this game does not have it. Open Help for what is missing."] = "L’assegnazione tasti richiede Codeware, che questo gioco non ha. Apri Aiuto per vedere cosa manca.",
    ["Key or button"] = "Tasto o pulsante",
    ["Left arrow"] = "Freccia sinistra",
    ["Menu"] = "Menu",
    ["No key was pressed, so nothing changed."] = "Nessun tasto premuto, quindi non è cambiato nulla.",
    ["Not available"] = "Non disponibile",
    ["Not set"] = "Non impostato",
    ["Num lock"] = "Bloc Num",
    ["Page down"] = "Pag giù",
    ["Page up"] = "Pag su",
    ["Pause"] = "Pausa",
    ["Press it, then the key or controller button you want. Esc or B cancels. It works at once."] = "Premilo, poi il tasto o il pulsante del controller che vuoi. Esc o B annulla. Funziona subito.",
    ["Press it to open the Companion Manager while you play."] = "Premilo per aprire Gestione compagni mentre giochi.",
    ["Press it to type to the character you face. Facing nobody, you type to the first member of your party."] = "Premilo per scrivere al personaggio che hai di fronte. Se non guardi nessuno, scrivi al primo membro del tuo gruppo.",
    ["Press it to type to Johnny, the voice in your head, wherever you face. It needs Johnny in your head turned on in Settings."] = "Premilo per scrivere a Johnny, la voce nella tua testa, ovunque tu guardi. Serve che Johnny nella tua testa sia attivato nelle Impostazioni.",
    ["Press it to type to the characters around you at once. Facing nobody, you type to the first member of your party and two others from it."] = "Premilo per scrivere a tutti i personaggi intorno a te insieme. Se non guardi nessuno, scrivi al primo membro del tuo gruppo e ad altri due del gruppo.",
    ["Press the key or controller button for {action}. Esc or B cancels."] = "Premi il tasto o il pulsante del controller per {action}. Esc o B annulla.",
    ["Print screen"] = "Stamp",
    ["Remove the key or button you set here."] = "Rimuovi il tasto o il pulsante impostato qui.",
    ["Right arrow"] = "Freccia destra",
    ["Scroll lock"] = "Bloc Scorr",
    ["Space"] = "Spazio",
    ["Tab"] = "Tab",
    ["Talk by text"] = "Parla per testo",
    ["Talk by voice"] = "Parla a voce",
    ["Talk to Johnny by text"] = "Parla con Johnny per testo",
    ["Talk to Johnny by voice"] = "Parla con Johnny a voce",
    ["That key is already used for another action."] = "Questo tasto è già usato per un’altra azione.",
    ["The mod’s key bindings could not be loaded. Open Help for what is wrong."] = "Non è stato possibile caricare le assegnazioni tasti della mod. Apri Aiuto per vedere cosa non va.",
    ["The mod’s scripts did not load, so no key can be set. Open Help for what is wrong."] = "Gli script della mod non sono stati caricati, quindi non si può impostare nessun tasto. Apri Aiuto per vedere cosa non va.",
    ["Up arrow"] = "Freccia su",
    ["View"] = "Visualizza",
    ["{action} cleared."] = "Assegnazione di {action} rimossa.",
    ["{action} is set to {key}."] = "{action} è impostato su {key}.",
    ["{key} is already used for {other}. Choose another."] = "{key} è già usato per {other}. Scegline un altro.",
    ["10 minutes"] = "10 minuti",
    ["2 minutes"] = "2 minuti",
    ["5 minutes"] = "5 minuti",
    ["Cancel this meeting. She is not told."] = "Annulla l’incontro. Lei non lo sa.",
    ["Car"] = "Auto",
    ["Choose how long she waits."] = "Scegli quanto deve aspettare.",
    ["Choose how she arrives."] = "Scegli come arriva.",
    ["Choose one of the listed options."] = "Scegli una delle opzioni elencate.",
    ["Choose when she arrives."] = "Scegli quando arriva.",
    ["Companions travel to you when you invite them: they walk or drive in, text you, wait, and remember if you never come.\n\nOff by default."] = "I compagni vengono da te quando li inviti: a piedi o in auto, ti scrivono, aspettano e ricordano se non arrivi.\n\nDisattivato di default.",
    ["Fine. Call me when you know what you want."] = "Va bene. Chiamami quando sai cosa vuoi.",
    ["How long she waits"] = "Quanto aspetta",
    ["How long she waits for you after arriving right now. After a timed arrival she waits as long as the delay you chose. The wait stops while you are in a fight, a scene or a menu."] = "Quanto tempo ti aspetta dopo l’arrivo immediato. Dopo un arrivo programmato aspetta quanto il ritardo scelto. L’attesa si ferma durante un combattimento, una scena o un menu.",
    ["How she arrives"] = "Come arriva",
    ["I waited {minutes} minutes at {place} and you never showed. Forget it."] = "Ti ho aspettato per {minutes} minuti a {place} e non sei venuto. Lascia perdere.",
    ["I'm here at {place}. Where are you?"] = "Sono qui a {place}. Dove sei?",
    ["Immersive invitations"] = "Inviti immersivi",
    ["In 10 minutes"] = "Tra 10 minuti",
    ["In 2 minutes"] = "Tra 2 minuti",
    ["In 5 minutes"] = "Tra 5 minuti",
    ["Invite a companion and she really travels to you: she appears out of sight, walks or drives in, texts you when she is there and waits for you."] = "Invita un compagno e lei arriva davvero da te: compare fuori dalla vista, arriva a piedi o in auto, ti scrive quando è lì e ti aspetta.",
    ["Meet at my waypoint when I ask"] = "Incontro al mio waypoint su richiesta",
    ["Off: Invite brings a companion to your side at once.\n\nOn: a companion you invite, by the Invite button, the Contacts tab or a text, travels to you and arrives after the time you choose here. She texts you when she is there, waits, and leaves angry (and remembers it) if you never come."] = "Disattivato: Inviti porta subito un compagno al tuo fianco.\n\nAttivato: un compagno che inviti, con il pulsante Invita, la scheda Contatti o un messaggio, raggiunge te e arriva dopo il tempo scelto qui. Ti scrive quando è lì, aspetta e se ne va arrabbiato (e lo ricorda) se non arrivi mai.",
    ["Right now"] = "Subito",
    ["Right now: she is on her way as soon as she is ready.\n\nIn 2, 5 or 10 minutes: real minutes of play, so she arrives at that time. She then waits as long as that delay."] = "Subito: si mette in strada appena è pronta.\n\nTra 2, 5 o 10 minuti: minuti di gioco reali, quindi arriva a quell’ora. Poi aspetta quanto quel ritardo.",
    ["She texts you"] = "Ti scrive",
    ["She texts you when she arrives, when you cancel and when she gives up. Off: no texts (she still remembers being stood up)."] = "Ti scrive quando arriva, quando annulli e quando rinuncia. Disattivato: nessun messaggio (ricorda comunque l’abbandono).",
    ["Something came up and I can't make it. Sorry."] = "Mi è capitato un imprevisto e non ce la faccio. Scusa.",
    ["Walk"] = "A piedi",
    ["Walk: she appears out of your sight and walks to you.\n\nCar: when a road is near she drives in, stops on the road, gets out and walks the rest. Without a road she walks. The car stays near for a ride, and is removed when she leaves your group or you both go far from it."] = "A piedi: compare fuori dalla tua vista e cammina fino a te.\n\nAuto: se c’è una strada vicina, arriva in auto, si ferma sulla strada, scende e fa il resto a piedi. Senza strada va a piedi. L’auto resta vicina per il viaggio e viene rimossa quando lascia il gruppo o quando vi allontanate entrambi.",
    ["When she arrives"] = "Quando arriva",
    ["When you ask her to come to your waypoint and a map pin is set, she goes there and says so. Off: she always comes to where you are."] = "Quando le chiedi di venire al tuo waypoint e c’è un segnaposto sulla mappa, va lì e lo dice. Disattivato: viene sempre dove sei.",
    ["Your position cannot be read yet."] = "La tua posizione non può ancora essere letta.",
    ["on her way"] = "in arrivo",
    ["the meeting spot"] = "il punto d’incontro",
    ["waiting at {place}"] = "in attesa a {place}",
    ["{name} is already on the way."] = "{name} è già in arrivo.",
    ["{name} is on her way."] = "{name} è in arrivo.",
    ["{name} is on her way. About {minutes} minutes."] = "{name} è in arrivo. Circa {minutes} minuti.",
    ["{name} · {state}"] = "{name} · {state}",
    ["{name}: Good to see you. Let us go."] = "{name}: Bello vederti. Andiamo.",
    ["Corpo Plaza"] = "Corpo Plaza",
    ["Heywood Glen"] = "Heywood Glen",
    ["Megabuilding H10"] = "Megabuilding H10",
    ["Move out"] = "Far traslocare",
    ["That companion is not available."] = "Questo compagno non è disponibile.",
    ["Watson Northside"] = "Watson Northside",
    ["Westbrook Japantown"] = "Westbrook Japantown",
    ["You do not have that apartment."] = "Non hai quell’appartamento.",
    ["at home"] = "a casa",
    ["out"] = "fuori",
    ["with you"] = "con te",
    ["{count} more housemates"] = "{count} altri coinquilini",
    ["{name} has moved out."] = "{name} non vive più da te.",
    ["{name} is back at home."] = "{name} è di nuovo a casa.",
    ["{name} joins you."] = "{name} si unisce a te.",
    ["{name} moves into {apartment}."] = "{name} si trasferisce in {apartment}.",
    ["{name} now lives in {apartment} and stays in your party until sent home."] = "{name} ora vive in {apartment} e resta nel tuo gruppo finché non torna a casa.",
    ["{name} stops living at your place. She stays as she is otherwise."] = "{name} non vive più da te. Il resto non cambia.",
    ["{name} · lives in {apartment} · {state}"] = "{name} · vive in {apartment} · {state}",
    ["Companions change outfits"] = "I compagni cambiano outfit",
    ["Your party’s companions change outfits now and then: another look by day and by night, and casual clothes at home, where the character has them.\n\nOnly out of your sight, never in front of you, and only for your party’s own copies, never the game’s own characters. Turning this off keeps what they wear now."] = "I compagni del tuo gruppo cambiano outfit di tanto in tanto: un altro look di giorno e uno di notte, e abiti casual a casa, dove il personaggio li ha.\n\nSolo fuori dalla tua vista, mai davanti a te, e solo per le copie del tuo gruppo, mai per i personaggi del gioco. Disattivando questa opzione restano con ciò che indossano in quel momento.",
    ["Choose how often companions speak up."] = "Scegli con che frequenza i compagni intervengono.",
    ["Companions speak up"] = "I compagni intervengono",
    ["How V is doing according to other mods, when they are installed: Dark Future’s tiredness, hunger, thirst, nerve and addictions, for example. Also what V visibly wears while an Equipment-EX outfit is on, so characters describe the outfit and not the clothes it hides.\n\nOff by default. Off: it is not sent, and nothing is read from those mods."] = "Come sta V secondo gli altri mod, se installati: per esempio stanchezza, fame, sete, nervi e dipendenze di Dark Future. Anche ciò che V indossa in modo visibile mentre è attivo un outfit di Equipment-EX, così i personaggi descrivono l’outfit e non i vestiti che nasconde.\n\nDisattivato per impostazione predefinita. Disattivato: non viene inviato nulla e da quei mod non si legge niente.",
    ["How long it has been since V last talked to this character, in the game and in real days: since last night, or days ago. Said only when the gap is long enough to matter, and not again in the same conversation.\n\nOff: it is not sent, and the mod stops reading the game clock for it."] = "Da quanto tempo V non parla con questo personaggio, nel gioco e in giorni reali: dalla scorsa notte, o da giorni. Viene detto solo quando il distacco è abbastanza lungo da contare, e non di nuovo nella stessa conversazione.\n\nDisattivato: non viene inviato nulla, e il mod smette di leggere l’orologio di gioco per questo.",
    ["Music and TV"] = "Musica e TV",
    ["Other mods’ state"] = "Stato degli altri mod",
    ["Speaks up normally"] = "Interviene normalmente",
    ["The song playing on the car radio while V rides with the character, or on V’s pocket radio, and what is on a TV near V.\n\nOff: it is not sent, and the mod stops reading it from the game."] = "La canzone che suona alla radio dell’auto quando V viaggia con il personaggio, o alla radio tascabile di V, e ciò che c’è in una TV vicino a V.\n\nDisattivato: non viene inviato nulla, e il mod smette di leggerla dal gioco.",
    ["Time since last talk"] = "Tempo dall’ultima conversazione",
    ["Companions in your party sometimes start talking on their own, at a calm moment or after a scene. With two or more near you, it is often a short chat between up to three of them, and you can join in by talking. Never during fights, scenes, calls or menus.\n\nRarely: about 2 an hour. Normally: about 4. Often (the default): about 6.\n\nWith Johnny speaking up too, the rates add up and they take turns."] = "I compagni a volte parlano di loro iniziativa, in un momento tranquillo o dopo una scena. Con due o più vicini, spesso è una breve chiacchierata tra al massimo tre, a cui puoi unirti parlando. Mai durante combattimenti, scene, chiamate o menu.\n\nRaramente: circa 2 all’ora di gioco. Normalmente: circa 4. Spesso (predefinito): circa 6.\n\nSe anche Johnny interviene, le due frequenze si sommano e si alternano.",
    ["Johnny Silverhand answers the Talk to Johnny keys, as the voice in V’s head, once the story has him there. Give Talk to Johnny a key on the Key bindings page: none is set by default.\n\nOn: he answers when you talk to him. Rarely: he also speaks up on his own, about 2 an hour. Normally: about 4. Often: about 6.\n\nWith companions speaking up too, the rates add up and they take turns."] = "Johnny Silverhand risponde ai tasti Parla con Johnny, come voce nella testa di V, quando la trama lo colloca lì. Assegna un tasto a Parla con Johnny nella pagina Assegnazione tasti: di default non ne è impostato nessuno.\n\nAttivo: risponde quando gli parli. Raramente: interviene da solo, circa 2 l’ora. Normalmente: circa 4. Spesso: circa 6.\n\nCon i compagni che intervengono, le frequenze si sommano e si alternano.",
    ["Choose which live game info the characters are told, such as location, time, weather, company, health, money, gear, quests, music and TV, and other mods’ state.\n\nAll on by default except other mods’ state, which is off. An off kind is not sent to any conversation provider."] = "Scegli quali informazioni di gioco in tempo reale vengono comunicate ai personaggi, come posizione, ora, meteo, compagnia, salute, denaro, equipaggiamento, missioni, musica e TV, e stato degli altri mod.\n\nTutto è attivo per impostazione predefinita, tranne lo stato di altre mod, che è disattivato. Un tipo disattivato non viene inviato a nessun fornitore di conversazione.",
    ["Housemates"] = "Coinquilini",
    ["Housemates talk to each other"] = "I coinquilini parlano tra loro",
    ["When two or more housemates are home with you, they talk to each other now and then."] = "Quando due o più coinquilini sono a casa con te, ogni tanto parlano tra loro.",
    ["Characters you tell they can stay at your place move into your apartments and live there."] = "I personaggi a cui dici che possono stare da te si trasferiscono nei tuoi appartamenti e ci vivono.",
    ["Characters you tell they can stay at your place move into your apartments and live there.\n\nOff by default."] = "I personaggi a cui dici che possono stare da te si trasferiscono nei tuoi appartamenti e ci vivono.\n\nDisattivato per impostazione predefinita.",
    ["On: characters you tell they can stay at your place move into your apartments and live there, and you can call them along.\n\nOff: nothing of this runs. Turning it off removes them from your apartments but remembers who lived there, so turning it on brings them back."] = "Attivato: i personaggi a cui dici che possono stare da te si trasferiscono nei tuoi appartamenti e ci vivono, e puoi portarli con te.\n\nDisattivato: niente di tutto questo è in funzione. Disattivandolo, lasciano i tuoi appartamenti, ma si ricorda chi ci viveva, quindi tornano quando lo riattivi.",
    ["OmniVoice Python"] = "OmniVoice Python",
    ["OmniVoice’s code could not load in it"] = "il codice di OmniVoice non ha potuto caricarsi",
    ["PyTorch is not installed in it"] = "PyTorch non è installato",
    ["Your own Python (omni-python.txt) is being tested. Open this page again in a minute."] = "Il tuo Python personale (omni-python.txt) è in fase di test. Apri di nuovo questa pagina tra un minuto.",
    ["Your own Python (omni-python.txt) is tested when OmniVoice starts or when this page checks again."] = "Il tuo Python personale (omni-python.txt) viene testato quando OmniVoice si avvia o quando questa pagina controlla di nuovo.",
    ["Your own Python (omni-python.txt) runs OmniVoice with {backend} on {card}. Experimental."] = "Il tuo Python personale (omni-python.txt) esegue OmniVoice con {backend} su {card}. Sperimentale.",
    ["Your own Python (omni-python.txt) was not used: {reason}. OmniVoice uses the Runtime’s Python, which needs an NVIDIA card."] = "Il tuo Python personale (omni-python.txt) non è stato utilizzato: {reason}. OmniVoice utilizza il Python del Runtime, che richiede una scheda NVIDIA.",
    ["a test on the graphics card failed"] = "un test sulla scheda grafica non è riuscito",
    ["it did not start or did not answer in time"] = "non si è avviato o non ha risposto in tempo",
    ["its PyTorch finds no graphics card (no CUDA or ROCm)"] = "il suo PyTorch non trova schede grafiche (senza CUDA o ROCm)",
    ["the OmniVoice pack is not installed"] = "il pacchetto OmniVoice non è installato",
    ["the file does not name a python.exe that exists"] = "il file non specifica un python.exe che esiste",
    ["the module {module} is missing in it"] = "il modulo {module} vi manca",
    ["1 minute"] = "1 minuto",
    ["2 people"] = "2 persone",
    ["3 people"] = "3 persone",
    ["4 people"] = "4 persone",
    ["Every character who lives at your place moves out at once, from every apartment. Party members who do not live there are not touched. A housemate who is with you stays in your party."] = "Ogni personaggio che vive da te si trasferisce tutto in una volta, da ogni appartamento. I membri del gruppo che non vivono lì non sono toccati. Un coinquilino che è con te rimane nel tuo gruppo.",
    ["Evict"] = "Far traslocare",
    ["Evict all housemates"] = "Far traslocare tutti i coinquilini",
    ["Housemates in one chat"] = "Coinquilini in una chat",
    ["Housemates moved out: {count}"] = "Coinquilini traslocati: {count}",
    ["How long the housemates stay quiet after a chat before they may start another. The Companions speak up setting still limits how many chats come in an hour."] = "Per quanto tempo i coinquilini rimangono in silenzio dopo una chat prima di poterne iniziare un'altra. L'impostazione I compagni intervengono limita ancora quante chat arrivano in un'ora.",
    ["How many housemates join one chat when that many are home near each other. They speak one at a time. With fewer at home, the chat is as big as it can be."] = "Quanti coinquilini si uniscono a una chat quando quel numero è a casa vicino l'uno all'altro. Parlano uno alla volta. Con meno a casa, la chat è grande quanto può essere.",
    ["Move-in apartment"] = "Appartamento di trasloco",
    ["Nobody lives at your place."] = "Nessuno vive da te.",
    ["Pause between chats"] = "Pausa tra le chat",
    ["Where a character moves in when you say she can stay but name no apartment and you are not standing in one of yours.\n\nAsk me: she asks which one. Otherwise she takes the apartment you pick here. Only the apartments you own are listed."] = "Dove un personaggio si trasferisce quando dici che può stare da te ma non nomini un appartamento e non sei in piedi in uno dei tuoi.\n\nChiedimi: lei chiede quale. Altrimenti prende l'appartamento che scegli qui. Sono elencati solo gli appartamenti che possiedi.",
    ["Ask me"] = "Chiedimi",
    ["Could not start"] = "Impossibile avviare",
    ["Did not start"] = "Non avviato",
    ["If the folder is there, the newest log in red4ext/logs says why RED4ext did not load it: an antivirus that removed a file, or a missing Visual C++ runtime."] = "Se la cartella c’è, il log più recente in red4ext/logs spiega perché RED4ext non l’ha caricata: un antivirus ha rimosso un file oppure manca il Visual C++ runtime.",
    ["Load a save first. A key can be set only while a game is loaded."] = "Carica prima un salvataggio. Un tasto si può impostare solo con una partita caricata.",
    ["No key press reached the mod, so nothing changed. If keys do not arrive from this menu, set the key in Cyber Engine Tweaks’ Bindings: it works the same."] = "Nessuna pressione di tasto è arrivata al mod, quindi non è cambiato nulla. Se i tasti non arrivano da questo menu, imposta il tasto nelle assegnazioni di Cyber Engine Tweaks: funziona allo stesso modo.",
    ["Runtime incomplete"] = "Runtime incompleto",
    ["Runtime not loaded"] = "Runtime non caricato",
    ["Service not running ({reason})"] = "Servizio non in esecuzione ({reason})",
    ["The Runtime’s plugin is loaded, but the conversation service left no trace in this session. launcher.log in red4ext/plugins/AiNpcCyberpunkCode says why: launcher.ini switched off, Node missing, or Node blocked by a security program. Fix that, then restart the game."] = "Il plugin del Runtime è caricato, ma il servizio di conversazione non ha lasciato tracce in questa sessione. launcher.log in red4ext/plugins/AiNpcCyberpunkCode spiega perché: launcher.ini disattivato, Node mancante o Node bloccato da un programma di sicurezza. Risolvi il problema, poi riavvia il gioco.",
    ["The conversation service cannot see this mod’s folder in the game: a mod manager’s virtual folders, or a folder it may not read. Extract the Runtime straight into the Cyberpunk 2077 folder, or start the game from the mod manager that holds the Runtime."] = "Il servizio di conversazione non riesce a vedere la cartella di questo mod nel gioco: cartelle virtuali di un gestore di mod, oppure una cartella che non può leggere. Estrai il Runtime direttamente nella cartella di Cyberpunk 2077, oppure avvia il gioco dal gestore di mod che contiene il Runtime.",
    ["The conversation service was started and never reported back. A security program probably stopped it at once, or Node cannot run on this PC. Allow red4ext/plugins/AiNpcCyberpunkMod/app/node/node.exe in your security program, then restart the game."] = "Il servizio di conversazione è stato avviato ma non ha mai risposto. Probabilmente un programma di sicurezza l’ha fermato subito, oppure Node non può funzionare su questo PC. Consenti red4ext/plugins/AiNpcCyberpunkMod/app/node/node.exe nel tuo programma di sicurezza, poi riavvia il gioco.",
    ["Windows would not let the game start the conversation service (error {error}). A security program may be blocking node.exe in red4ext/plugins/AiNpcCyberpunkMod/app/node: allow it, then restart the game."] = "Windows non ha permesso al gioco di avviare il servizio di conversazione (errore {error}). Un programma di sicurezza potrebbe bloccare node.exe in red4ext/plugins/AiNpcCyberpunkMod/app/node: consentilo, poi riavvia il gioco.",
    ["Add a server address first."] = "Aggiungere prima un indirizzo del server.",
    ["Asks the server three times who it is and shows whether it is reachable, how long it takes to answer and its version. It sends no speech."] = "Chiede tre volte al server chi è e mostra se è raggiungibile, quanto impiega a rispondere e la sua versione. Non invia alcun parlato.",
    ["Connected. The server speaks with {voice}."] = "Connesso. Il server parla con {voice}.",
    ["Custom voices"] = "Voci personalizzate",
    ["Deletes the saved server address. Remote OmniVoice needs one to speak."] = "Elimina l’indirizzo del server salvato. OmniVoice remoto ne ha bisogno per parlare.",
    ["It answers in {ms} ms."] = "Risponde in {ms} ms.",
    ["Its voice runs on {device}."] = "La sua voce viene eseguita su {device}.",
    ["Loading"] = "Caricamento",
    ["Not connected. Replies show as text until the server answers."] = "Non connesso. Le risposte vengono mostrate come testo finché il server non risponde.",
    ["Nothing answered at that address. Check that the server is running, that the address and port are right and that both PCs are on the same network. A server started with its default only listens on its own PC: start it with the listen address 0.0.0.0."] = "Nessuna risposta da quell’indirizzo. Verificare che il server sia in esecuzione, che indirizzo e porta siano corretti e che entrambi i PC siano sulla stessa rete. Un server avviato con le impostazioni predefinite ascolta solo sul proprio PC: avvialo con l’indirizzo di ascolto 0.0.0.0.",
    ["Off. OmniVoice runs on this PC."] = "Disattivato. OmniVoice viene eseguito su questo PC.",
    ["On, but no server address is saved. OmniVoice cannot speak yet."] = "Attivo, ma non è salvato alcun indirizzo del server. OmniVoice non può ancora parlare.",
    ["On, but no server address is saved. Pocket is used until you add one."] = "Attivo, ma non è salvato alcun indirizzo del server. Finché non ne aggiungi uno, viene usato Pocket.",
    ["On, but no server address is saved. The server is not used yet."] = "Attivo, ma non è salvato alcun indirizzo del server. Il server non è ancora usato.",
    ["On, but a cloud voice is chosen under Companion voices, so the server is not used."] = "Attivo, ma tra le Voci dei compagni è scelta una voce nel cloud, quindi il server non viene usato.",
    ["On. Waiting for the conversation service."] = "Attivo. In attesa del servizio di conversazione.",
    ["Paste address"] = "Incolla indirizzo",
    ["Remote OmniVoice"] = "OmniVoice remoto",
    ["Render the voices on another PC or graphics card that runs the OmniVoice server, so this PC keeps its frames.\n\nTurn it on, press Apply and add the server address below. The server then speaks for every Pocket or OmniVoice choice under Companion voices; a cloud voice stays as chosen. If it cannot be reached, replies show as text and the mod retries every few seconds."] = "Genera le voci su un altro PC o scheda grafica che esegue il server OmniVoice, così questo PC mantiene i suoi fotogrammi.\n\nAttivalo, premi Applica e aggiungi qui sotto l’indirizzo del server. Il server parla poi per ogni scelta Pocket o OmniVoice in Voci dei compagni; una voce nel cloud resta come scelta. Se il server non è raggiungibile, le risposte vengono mostrate come testo e il mod riprova ogni pochi secondi.",
    ["Render the OmniVoice voices on another PC or graphics card that runs the OmniVoice server."] = "Genera le voci OmniVoice su un altro PC o scheda grafica che esegue il server OmniVoice.",
    ["Render Pocket and OmniVoice voices on another PC or graphics card: the on/off switch, the server address and a connection test. It works whichever of those voices is chosen above."] = "Genera le voci Pocket e OmniVoice su un altro PC o scheda grafica: l’interruttore di attivazione, l’indirizzo del server e un test di connessione. Funziona qualunque di queste voci sia scelta sopra.",
    ["Server address"] = "Indirizzo del server",
    ["Something answered, but it is not the OmniVoice server. Check the port."] = "Ha risposto qualcosa, ma non è il server OmniVoice. Controllare la porta.",
    ["Start the OmniVoice server on the other PC. Its window shows the address to use, for example 192.168.1.20:8765. Copy it, then choose Paste address. It is read from the clipboard once and saved on this computer.\n\nOn the same PC use 127.0.0.1:8765. You can also write address=192.168.1.20:8765 in player-remote-omnivoice.txt in the conversation service folder.\n\nNothing is sent to it until Remote OmniVoice is on and OmniVoice is chosen, or you press Test."] = "Avvia il server OmniVoice sull’altro PC. La sua finestra mostra l’indirizzo da usare, per esempio 192.168.1.20:8765. Copialo, quindi scegli Incolla indirizzo. Viene letto dagli appunti una sola volta e salvato su questo computer.\n\nSullo stesso PC usa 127.0.0.1:8765. Puoi anche scrivere address=192.168.1.20:8765 in player-remote-omnivoice.txt nella cartella del servizio di conversazione.\n\nNon viene inviato nulla finché OmniVoice remoto non è attivo e OmniVoice non è selezionato, oppure finché non premi Prova.",
    ["Status"] = "Stato",
    ["The OmniVoice server cannot be reached. Replies show as text until it answers. The mod asks it again every few seconds."] = "Impossibile raggiungere il server OmniVoice. Le risposte vengono mostrate come testo finché non risponde. Il mod lo ricontatta ogni pochi secondi.",
    ["The clipboard does not hold a server address."] = "Gli appunti non contengono un indirizzo del server.",
    ["The clipboard is empty. Copy the address first."] = "Gli appunti sono vuoti. Copia prima l’indirizzo.",
    ["The port must be a number from 1 to 65535."] = "La porta deve essere un numero da 1 a 65535.",
    ["The server address was removed."] = "L’indirizzo del server è stato rimosso.",
    ["The server answered but could not load its voice. Its window says why."] = "Il server ha risposto, ma non ha potuto caricare la sua voce. La sua finestra indica il motivo.",
    ["The server answered but is still loading its voice. Try again in a minute."] = "Il server ha risposto, ma sta ancora caricando la sua voce. Riprova tra un minuto.",
    ["The server is another version. Use the server folder and the mod from the same release."] = "Il server è di un’altra versione. Usa la cartella del server e il mod della stessa release.",
    ["The server is ready."] = "Il server è pronto.",
    ["The server refused the request."] = "Il server ha rifiutato la richiesta.",
    ["The server took too long to answer."] = "Il server ha impiegato troppo tempo a rispondere.",
    ["Use the address only: no user name, no path, no #."] = "Inserisci solo l’indirizzo: niente nome utente, niente percorso, niente #.",
    ["Use the address the server window shows, such as 192.168.1.20:8765, without https://."] = "Usa l’indirizzo mostrato dalla finestra del server, come 192.168.1.20:8765, senza https://.",
    ["Waiting for the server to answer…"] = "In attesa che il server risponda…",
    ["Whether the server is in use right now. It is checked when a voice is needed and again every few seconds after a failure, never while you play."] = "Indica se il server è in uso in questo momento. Viene controllato quando serve una voce e di nuovo ogni pochi secondi dopo un errore, mai mentre giochi.",
    ["Your own character, made in the character editor."] = "Il tuo personaggio, creato nell’editor dei personaggi.",
    ["Build for your game"] = "Build per il tuo gioco",
    ["Your game is {game} but the Runtime is the one for game {runtime}. Get the full install zip for game {game} from the mod’s Nexus Mods page (main file for game 2.5, optional file for game 2.31) and extract it into the Cyberpunk 2077 folder over this one, then restart the game."] = "Il tuo gioco è {game} ma il Runtime è quello per il gioco {runtime}. Scarica lo zip di installazione completo per il gioco {game} dalla pagina Nexus Mods della mod (file principale per il gioco 2.5, file facoltativo per il gioco 2.31), estrailo nella cartella di Cyberpunk 2077 sopra quella attuale, poi riavvia il gioco.",
    ["Your game is {game} but the Scripts are the build for game {scripts}. Get the update zip for game {game} from the mod’s Nexus Mods page (the update file is for game 2.5, the optional update file for game 2.31) and install it over these, then restart the game."] = "Il tuo gioco è {game} ma gli Scripts sono la build per il gioco {scripts}. Scarica lo zip di aggiornamento per il gioco {game} dalla pagina Nexus Mods della mod (il file di aggiornamento è per il gioco 2.5, il file di aggiornamento facoltativo per il gioco 2.31), installalo sopra quelli attuali, poi riavvia il gioco.",
    ["Your game is {game} but the Scripts and the Runtime are the build for game {scripts}. Get the full install zip for game {game} from the mod’s Nexus Mods page (main file for game 2.5, optional file for game 2.31) and extract it into the Cyberpunk 2077 folder over these, then restart the game."] = "Il tuo gioco è {game} ma gli Scripts e il Runtime sono la build per il gioco {scripts}. Scarica lo zip di installazione completo per il gioco {game} dalla pagina Nexus Mods della mod (file principale per il gioco 2.5, file facoltativo per il gioco 2.31), estrailo nella cartella di Cyberpunk 2077 sopra quelli attuali, poi riavvia il gioco.",
    ["The Scripts are the build for game {scripts} but the Runtime is the build for game {runtime}, and the game version matches neither. Extract the full install zip made for the same game as yours (from Nexus Mods) into the Cyberpunk 2077 folder, then restart the game."] = "Gli Scripts sono la build per il gioco {scripts} ma il Runtime è la build per il gioco {runtime}, e la versione del gioco non corrisponde a nessuno dei due. Estrai nella cartella di Cyberpunk 2077 lo zip di installazione completo fatto per lo stesso gioco del tuo (da Nexus Mods), poi riavvia il gioco.",
    ["The Runtime is for game {other}, yours is {game}. Get the full install zip for {game}."] = "Runtime per il gioco {other}, il tuo è {game}. Scarica lo zip completo per {game}.",
    ["The Scripts are for game {other}, yours is {game}. Get the update zip for {game}."] = "Scripts per il gioco {other}, il tuo è {game}. Scarica lo Update-ZIP per {game}.",
    ["This mod is for game {other}, yours is {game}. Get the full install zip for {game}."] = "Mod per il gioco {other}, il tuo è {game}. Scarica lo zip completo per {game}.",
    ["Scripts are for game {scripts}, Runtime for {runtime}. They must match. See Help in Settings."] = "Scripts {scripts}, Runtime {runtime}. Devono corrispondere: vedi Aiuto in Impostazioni.",
    ["Choose one of the listed microphones."] = "Scegli uno dei microfoni nell'elenco.",
    ["Microphone"] = "Microfono",
    ["The microphone you chose in Settings ({chosen}) is not connected, so the Windows default input is used: {name}."] = "Il microfono scelto nelle Impostazioni ({chosen}) non è connesso, quindi viene usato l'ingresso predefinito di Windows: {name}.",
    ["The microphone you chose in Settings is not connected, so the Windows default input is used."] = "Il microfono scelto nelle Impostazioni non è connesso, quindi viene usato l'ingresso predefinito di Windows.",
    ["Windows default"] = "Predefinito di Windows",
    ["not connected"] = "non connesso",
    ["{name}, chosen in Settings > Voices."] = "{name}, scelto in Impostazioni > Voci.",
    ["{name}, the Windows default input. Settings > Voices > Microphone chooses another."] = "{name}, l'ingresso predefinito di Windows. Impostazioni > Voci > Microfono ne sceglie un altro.",
    ["Revenge ambushes"] = "Agguati di vendetta",
    ["Speak dialogue choices"] = "Pronuncia le scelte di dialogo",
    ["Say a dialogue choice to pick it: its words, a part of them, or its number (\"two\", \"the last one\"). If nothing fits clearly, nothing is picked. No character answers.\n\nPresses the arrow keys and Enter, so the game must be in front. Needs speech recognition on this PC. Headphones work best."] = "Pronuncia una scelta di dialogo per selezionarla: le sue parole, una parte di esse o il suo numero (\"due\", \"l'ultima\"). Se nulla corrisponde chiaramente, non viene selezionato nulla. Nessun personaggio risponde.\n\nPreme i tasti freccia e Enter, quindi il gioco deve essere in primo piano. Richiede il riconoscimento vocale su questo PC. Le cuffie funzionano meglio.",
    ["No option matched. Say its number."] = "Nessuna scelta corrisponde. Dì il suo numero.",
    ["Two options fit. Say its number."] = "Due scelte corrispondono. Dì il suo numero.",
    ["Speaking a choice needs speech recognition on this PC."] = "Dire una scelta richiede il riconoscimento vocale su questo PC.",
    ["AMD’s ROCm PyTorch does not support this card yet."] = "Il ROCm PyTorch di AMD non supporta ancora questa scheda.",
    ["Another setup is already running. Wait for it to finish."] = "Un’altra configurazione è già in corso. Attendi che finisca.",
    ["Cancelled"] = "Annullato",
    ["Cancelling…"] = "Annullamento…",
    ["Checking your card…"] = "Verifica della scheda…",
    ["Downloading {done} of {total} MB ({percent}%)"] = "Download di {done} di {total} MB ({percent}%)",
    ["Downloading…"] = "Download in corso…",
    ["Experimental. Pocket speaks until it is ready. A local voice never switches to a cloud voice."] = "Sperimentale. Pocket parla finché non è pronto. Una voce locale non passa mai a una voce cloud.",
    ["Frees about {disk} GB."] = "Libera circa {disk} GB.",
    ["Frees the space it took."] = "Libera lo spazio che occupava.",
    ["Install"] = "Installa",
    ["Installed"] = "Installato",
    ["Installed. OmniVoice uses it when it starts."] = "Installato. OmniVoice lo usa quando si avvia.",
    ["It is kept in the mod’s data folder on drive C:."] = "È conservato nella cartella dati del mod sul disco C:.",
    ["It runs in the background while you play. The game keeps running and nothing else changes."] = "Gira in background mentre giochi. Il gioco continua a girare e non cambia nient’altro.",
    ["It takes about {disk} GB on drive C: in the mod’s data folder."] = "Occupa circa {disk} GB sul disco C:, nella cartella dati del mod.",
    ["MIOpen convolutions (AMD)"] = "Convoluzioni MIOpen (AMD)",
    ["Not available on this PC. It needs an AMD Radeon card and the OmniVoice pack."] = "Non disponibile su questo PC. Serve una scheda AMD Radeon e il pack OmniVoice.",
    ["OmniVoice for AMD"] = "OmniVoice per AMD",
    ["OmniVoice on AMD: set up first"] = "OmniVoice su AMD: configuralo prima",
    ["OmniVoice then no longer starts on this card until it is set up again."] = "OmniVoice poi non si avvia più su questa scheda finché non viene configurato di nuovo.",
    ["On: AMD’s MIOpen runs the convolutions, with MIOPEN_FIND_MODE=2 and MIOPEN_FIND_ENFORCE=1. Off: PyTorch’s own convolutions. Which is faster depends on your card and driver: if voices are slow or stop part-way, try the other one. AMD cards only. OmniVoice restarts with the new choice when it is idle."] = "Attiva: MIOpen di AMD esegue le convoluzioni, con MIOPEN_FIND_MODE=2 e MIOPEN_FIND_ENFORCE=1. Disattiva: le convoluzioni di PyTorch. Quale sia più veloce dipende dalla scheda e dal driver: se le voci sono lente o si interrompono a metà, prova l’altra. Solo schede AMD. OmniVoice si riavvia con la nuova scelta quando è inattivo.",
    ["Own Python"] = "Python personale",
    ["Ready"] = "Pronto",
    ["Ready. OmniVoice runs on {card} with AMD’s ROCm."] = "Pronto. OmniVoice gira su {card} con ROCm di AMD.",
    ["Reinstall"] = "Reinstalla",
    ["Remove AMD setup"] = "Rimuovi la configurazione AMD",
    ["Removing the AMD setup…"] = "Rimozione della configurazione AMD in corso…",
    ["Run OmniVoice on your AMD Radeon card with AMD’s ROCm: one download, set up from here."] = "Fai girare OmniVoice sulla tua scheda AMD Radeon con ROCm di AMD: un solo download, configurato da qui.",
    ["Set up OmniVoice for AMD"] = "Configura OmniVoice per AMD",
    ["Starting the AMD setup…"] = "Avvio della configurazione AMD…",
    ["Testing it on your card…"] = "Prova sulla tua scheda…",
    ["The AMD setup was removed."] = "La configurazione AMD è stata rimossa.",
    ["The OmniVoice pack is not installed. Install it first."] = "Il pack OmniVoice non è installato. Installalo prima.",
    ["The conversation service is not running. Restart the game."] = "Il servizio di conversazione non è in esecuzione. Riavvia il gioco.",
    ["The download did not finish. Check your connection and try again."] = "Il download non è terminato. Controlla la connessione e riprova.",
    ["The download is not ready yet in this version of the mod."] = "Il download non è ancora pronto in questa versione del mod.",
    ["The downloaded files did not check out. Try again."] = "I file scaricati non hanno superato il controllo. Riprova.",
    ["The files could not be unpacked. Try again."] = "Non è stato possibile estrarre i file. Riprova.",
    ["The setup did not finish. Try again."] = "La configurazione non è terminata. Riprova.",
    ["The setup did not pass the test on your card, so OmniVoice cannot use it."] = "La configurazione non ha superato il test sulla tua scheda, quindi OmniVoice non può usarla.",
    ["The setup is installed but did not pass the test on your card. Choose Reinstall."] = "La configurazione è installata ma non ha superato il test sulla tua scheda. Scegli Reinstalla.",
    ["There is not enough free space on drive C:. Free some up and try again."] = "Non c’è abbastanza spazio libero sul disco C:. Liberane un po’ e riprova.",
    ["This PC has no AMD Radeon card this setup can use."] = "Questo PC non ha una scheda AMD Radeon che questa configurazione può usare.",
    ["Unpacking…"] = "Estrazione in corso…",
    ["Your own Python (omni-python.txt) is used instead. Delete that file to use this setup."] = "Viene usato invece il tuo Python (omni-python.txt). Elimina quel file per usare questa configurazione.",
    ["your AMD card"] = "la tua scheda AMD",
    ["{voice} · AMD: set up first"] = "{voice} · AMD: configuralo prima",
    ["The AMD setup (Settings > Voices > OmniVoice for AMD) runs OmniVoice with ROCm on {card}. Experimental."] = "La configurazione AMD (Impostazioni > Voci > OmniVoice per AMD) fa girare OmniVoice con ROCm su {card}. Sperimentale.",
    ["The AMD setup was not used: {reason}. Choose Reinstall in Settings > Voices > OmniVoice for AMD. Until then Pocket speaks."] = "La configurazione AMD non è stata usata: {reason}. Scegli Reinstalla in Impostazioni > Voci > OmniVoice per AMD. Fino ad allora parla Pocket.",
    ["Borrow eddies from your characters, lend them eddies and pay each other back, by talking. Each character has money of their own, as their story has it, and decides by how they feel about you. Now and then they ask you for a loan.\n\nEddies change hands as soon as a character agrees, and only with your own characters (party, invited visitors, housemates). The game’s own characters only talk about it. Off by default."] = "Parlando, chiedi eddies in prestito ai personaggi, prestane a loro e restituitevi a vicenda. Ognuno ha i suoi soldi e decide in base a come si sente con te. Ogni tanto chiedono un prestito.\n\nGli eddies cambiano di mano non appena un personaggio acconsente, e solo con i tuoi personaggi (gruppo, visitatori, coinquilini). I personaggi del gioco ne parlano solo. Disattivato di default.",
    ["Eddies with characters"] = "Eddies con i personaggi",
    ["The eddies could not be moved."] = "Non è stato possibile spostare gli eddies.",
    ["You do not have enough eddies for that."] = "Non hai abbastanza eddies per questo.",
    ["{name} is no longer with you, so no eddies moved."] = "{name} non è più con te, quindi nessuno spostamento di eddies è avvenuto.",
    ["Add to favorites"] = "Aggiungi ai preferiti",
    ["One download of about {size} GB."] = "Un solo download di circa {size} GB.",
    ["One download."] = "Un solo download.",
    ["Use the Search box, top right"] = "Usa la casella di ricerca",
    ["Search by name"] = "Cerca per nome",
    ["Search"] = "Cerca",
    ["The search box could not open."] = "Impossibile aprire la casella di ricerca.",
    ["Type part of a name"] = "Scrivi parte del nome",
    ["Opens a text box over the game. Type part of a name and press Enter: the list shows every match on every page and letter. Esc leaves the list as it is, and Enter on an empty box shows the whole list again. Case and accents do not matter, and every word you type has to match the start of a word in the name."] = "Apre una casella di testo sopra il gioco. Scrivi parte di un nome e premi Invio: la lista mostra tutte le corrispondenze in tutte le pagine e lettere. Esc lascia la lista com’è, e Invio in una casella vuota mostra di nuovo tutta la lista. Maiuscole e accenti non contano, e ogni parola scritta deve corrispondere all’inizio di una parola del nome.",
    ["How to search"] = "Come cercare",
    ["search: {query} · {count} found"] = "ricerca: {query} · {count} trovati",
    ["Empties the Search box and shows the whole list again."] = "Svuota la casella di ricerca e mostra di nuovo tutta la lista.",
    ["Click the Search box at the top right of this panel (it is dim until you click it) and type a name. The list shows every match on every page and letter. Case and accents do not matter, and every word you type has to match the start of a word in the name."] = "Fai clic sulla casella di ricerca in alto a destra di questo pannello (resta attenuata finché non ci fai clic) e scrivi un nome. La lista mostra tutte le corrispondenze in tutte le pagine e lettere. Maiuscole e accenti non contano, e ogni parola scritta deve corrispondere all’inizio di una parola del nome.",
    ["Click the Search box at the top right of this panel and type a name."] = "Fai clic sulla casella di ricerca in alto a destra di questo pannello e scrivi un nome.",
    ["Remove {name} from favorites"] = "Rimuovi {name} dai preferiti",
    ["Remove {name}"] = "Rimuovi {name}",
    ["Set up OmniVoice on your AMD Radeon card with one download, and choose how it runs."] = "Configura OmniVoice sulla tua scheda AMD Radeon con un solo download e scegli come gira.",
    ["That entry cannot be a favorite."] = "Quella voce non può essere un preferito.",
    ["You have too many favorites. Remove one first."] = "Hai troppi preferiti. Rimuovine prima uno.",
    ["Your AMD Radeon card ({card}) can run OmniVoice. Set it up in Settings > Voices > OmniVoice for AMD: one download, then it starts by itself."] = "La tua scheda AMD Radeon ({card}) può far girare OmniVoice. Configuralo in Impostazioni > Voci > OmniVoice per AMD: un download, poi parte da solo.",
    ["Your favorites could not be saved, so they last only until the game closes."] = "I tuoi preferiti non sono stati salvati, quindi durano solo fino alla chiusura del gioco.",
    ["{count} matching characters"] = "{count} personaggi corrispondenti",
    ["{name} is no longer a favorite."] = "{name} non è più un preferito.",
    ["A saved party holds {count} characters, so the rest were left out."] = "Un gruppo salvato contiene {count} personaggi, quindi il resto è stato escluso.",
    ["Already with you: {names}."] = "Già con te: {names}.",
    ["Another saved party already has that name."] = "Un altro gruppo salvato ha già questo nome.",
    ["Could not invite: {names}."] = "Impossibile invitare: {names}.",
    ["Deletes this saved party. The characters in your party now are not touched."] = "Elimina questo gruppo salvato. I personaggi del tuo gruppo attuale non vengono toccati.",
    ["Invites the characters of this party to your side: {names}.\n\nIt adds to your party and dismisses nobody. A character who is already with you is not invited twice. Anyone who cannot come is named, with the reason."] = "Invita al tuo fianco i personaggi di questo gruppo: {names}.\n\nSi aggiungono al tuo gruppo e non viene congedato nessuno. Un personaggio già con te non viene invitato due volte. Chi non può venire viene segnalato con il motivo.",
    ["Parties"] = "Gruppi",
    ["Party"] = "Gruppo",
    ["Press Delete again to delete {name}."] = "Premi di nuovo Elimina per eliminare {name}.",
    ["Press again"] = "Premi di nuovo",
    ["Press again to delete this saved party. Anything else cancels."] = "Premi di nuovo per eliminare questo gruppo salvato. Qualsiasi altra cosa annulla.",
    ["Rename"] = "Rinomina",
    ["Rename party"] = "Rinomina gruppo",
    ["Renamed to {name}."] = "Rinominato in {name}.",
    ["Replaces the characters of this saved party with the ones in your party now."] = "Sostituisce i personaggi di questo gruppo salvato con quelli del tuo gruppo attuale.",
    ["Save current party"] = "Salva gruppo attuale",
    ["Saved as {name}. Press Spawn party under it to invite them again."] = "Salvato come {name}. Premi Invita gruppo sotto di esso per invitarli di nuovo.",
    ["Saved party: {name}"] = "Gruppo salvato: {name}",
    ["Saves the characters in your party now, copies and your own characters included, as a party you can invite again with one press. It is named Party 1, Party 2 and so on, and appears below.\n\nYou keep up to {count} saved parties."] = "Salva i personaggi del tuo gruppo attuale, comprese le copie e i tuoi personaggi, come un gruppo che puoi invitare di nuovo con un solo tasto. Si chiama Gruppo 1, Gruppo 2 e così via, e compare qui sotto.\n\nPuoi conservare fino a {count} gruppi salvati.",
    ["Spawn"] = "Invita",
    ["Spawn party"] = "Invita gruppo",
    ["That party no longer exists."] = "Quel gruppo non esiste più.",
    ["The characters of this party: {names}."] = "I personaggi di questo gruppo: {names}.",
    ["The party could not be saved."] = "Impossibile salvare il gruppo.",
    ["This menu has no text box, so the party keeps its name. Mod Configuration Menu has one: type the name in its Search box."] = "Questo menu non ha un campo di testo, quindi il gruppo mantiene il suo nome. Mod Configuration Menu ce l'ha: scrivi il nome nel suo campo di ricerca.",
    ["Type the new name in the Search box at the top (Mod Configuration Menu), then press Rename. Native Settings UI has no text box, so a party keeps its name there."] = "Scrivi il nuovo nome nel campo di ricerca in alto (Mod Configuration Menu), poi premi Rinomina. Native Settings UI non ha un campo di testo, quindi lì un gruppo mantiene il suo nome.",
    ["Type the new name in the Search box first, then press Rename."] = "Scrivi prima il nuovo nome nel campo di ricerca, poi premi Rinomina.",
    ["Update"] = "Aggiorna",
    ["Update with current party"] = "Aggiorna con gruppo attuale",
    ["You can keep {count} saved parties. Delete one first."] = "Puoi conservare {count} gruppi salvati. Elimina prima uno di quelli.",
    ["Your party is empty. Invite someone first."] = "Il tuo gruppo è vuoto. Invita prima qualcuno.",
    ["Your saved parties could not be written to disk, so they last only until the game closes."] = "Impossibile scrivere i gruppi salvati sul disco, quindi resteranno solo fino alla chiusura del gioco.",
    ["that character model is unavailable"] = "il modello del personaggio non è disponibile",
    ["the invitation was refused"] = "l'invito è stato rifiutato",
    ["{name} ({count})"] = "{name} ({count})",
    ["{name} ({reason})"] = "{name} ({reason})",
    ["{name} deleted."] = "Eliminato: {name}.",
    ["{name} has nobody to invite."] = "{name} non ha nessuno da invitare.",
    ["{name} now has the characters of your party."] = "{name} ora ha i personaggi del tuo gruppo.",
    ["{party}: inviting {names}."] = "{party}: invito di {names} in corso.",
    ["Adds {name} to your favorites. They are listed at the top of page 1, and first in the phone’s Chat tab. Updates never touch them."] = "Aggiunge {name} ai preferiti. Compaiono in cima alla pagina 1 e per primi nella scheda Chat del telefono. Gli aggiornamenti non li toccano mai.",
    ["Favorites"] = "Preferiti",
    ["Only the first {count} favorites are listed here. The others are in the list below."] = "Qui sono elencati solo i primi {count} preferiti. Gli altri sono nella lista sottostante.",
    ["Page {page} of {pages}: {kind} {first} to {last}."] = "Pagina {page} di {pages}: {kind} da {first} a {last}.",
    ["Press to go to page {page} of {pages}: {kind} {first} to {last}."] = "Premi per andare alla pagina {page} di {pages}: {kind} da {first} a {last}.",
    ["Takes {name} out of your favorites. Her place in the list below stays."] = "Rimuove {name} dai preferiti. Il suo posto nella lista qui sotto resta.",
    ["This is the first page."] = "Questa è la prima pagina.",
    ["This is the last page."] = "Questa è l’ultima pagina.",
    ["characters"] = "personaggi",
    ["entries"] = "voci",
    ["models"] = "modelli",
    ["{count} more favorites"] = "Altri {count} preferiti",
    ["{name} is now a favorite. Favorites are at the top of page 1."] = "{name} è ora un preferito. I preferiti sono in cima alla pagina 1.",
    ["Favorite"] = "Preferito",
    ["That look is not one of this character’s."] = "Questo look non appartiene a questo personaggio.",
    ["That choice is not available."] = "Questa scelta non è disponibile.",
    ["The editor keeps choices for {max} characters. Reset one first."] = "L’editor conserva le scelte per {max} personaggi. Prima ripristinane una.",
    ["Usual look"] = "Look abituale",
    ["Home clothes: tank top, boxer shorts, flip-flops"] = "Abiti di casa: canottiera, boxer, infradito",
    ["No jacket"] = "Senza giacca",
    ["No jacket and harness"] = "Senza giacca e con imbragatura",
    ["Home clothes: shirt and trousers"] = "Abiti di casa: camicia e pantaloni",
    ["Home clothes: tank top and trousers"] = "Abiti di casa: canottiera e pantaloni",
    ["Hooded jacket"] = "Giacca con cappuccio",
    ["Home clothes: t-shirt and trousers"] = "Abiti di casa: maglietta e pantaloni",
    ["Collar down"] = "Colletto abbassato",
    ["Valentino look"] = "Look Valentino",
    ["Suit"] = "Completo",
    ["Club night, no jacket"] = "Serata in discoteca, senza giacca",
    ["Solo look"] = "Look Solo",
    ["Date night"] = "Serata romantica",
    ["T-shirt"] = "Maglietta",
    ["Vest"] = "Gilet",
    ["Paradise look"] = "Look Paradise",
    ["Bartender"] = "Barman",
    ["Dress without the fur coat"] = "Abito senza il cappotto di pelliccia",
    ["Trench coat"] = "Trench",
    ["Without the coat"] = "Senza il cappotto",
    ["CEO look with coat"] = "Look CEO con cappotto",
    ["CEO look"] = "Look CEO",
    ["Pyjamas"] = "Pigiama",
    ["Valentino look, collar open"] = "Look Valentino, colletto aperto",
    ["Vest and rucksack"] = "Gilet e zaino",
    ["Arasaka work clothes, no jacket"] = "Abiti da lavoro Arasaka, senza giacca",
    ["Red parade dress"] = "Abito rosso da parata",
    ["Red parade dress with bracelets"] = "Abito rosso da parata con bracciali",
    ["Party dress"] = "Abito da festa",
    ["Tank top"] = "Canottiera",
    ["Street clothes"] = "Abiti da strada",
    ["Merc look"] = "Look da mercenario",
    ["Go back to the usual look and moves for {name}? Your choices on this part are removed."] = "Tornare al look e ai movimenti abituali di {name}? Le tue scelte per questa parte verranno rimosse.",
    ["Back to the usual look and moves."] = "Ripristinati il look e i movimenti abituali.",
    ["Choices for how this character looks and moves. They work with every conversation option, Convai included, except the reply length."] = "Scelte su come questo personaggio appare e si muove. Funzionano con ogni opzione di conversazione, Convai compreso, tranne la lunghezza delle risposte.",
    ["Outfit"] = "Outfit",
    ["Automatic follows the “Companions change outfits” setting in the game: day and night looks, now and then a change, and casual clothes at home. A look you pick is worn all the time. Only your own companions and residents are dressed, and they change while nobody is looking. Characters the game places are never changed."] = "Automatico segue l’impostazione “I compagni cambiano outfit” del gioco: look di giorno e di notte, ogni tanto un cambio e abiti casual in casa. Un look scelto da te viene indossato sempre. Cambiano outfit solo i tuoi compagni e i residenti, e lo fanno quando nessuno guarda. I personaggi piazzati dal gioco non vengono mai cambiati.",
    ["This character has only one look in the game files, so there is no outfit to choose."] = "Questo personaggio ha un solo look nei file di gioco, quindi non c’è nessun outfit da scegliere.",
    ["Talking gestures"] = "Gesti mentre parla",
    ["How the hands move while they speak a longer reply."] = "Come si muovono le mani quando risponde con frasi più lunghe.",
    ["Normal"] = "Normale",
    ["Calm: smaller gestures, not as often"] = "Calmo: gesti più piccoli, meno frequenti",
    ["Lively: bigger gestures, more often"] = "Vivace: gesti più ampi, più frequenti",
    ["None: the hands stay at rest"] = "Nessuno: le mani restano ferme",
    ["Nod while you talk to them"] = "Annuisce mentre si conversa",
    ["A small nod now and then while you speak."] = "Un piccolo cenno del capo ogni tanto mentre parli.",
    ["Idle moves"] = "Movimenti da fermo",
    ["What they do now and then while they stand beside you."] = "Cosa fa ogni tanto mentre resta in piedi accanto a te.",
    ["Plain stances only, no props like a cup or a cigarette"] = "Solo posizioni semplici, senza oggetti come tazza o sigaretta",
    ["None: they keep the stance they have"] = "Nessuno: mantengono la posa attuale",
    ["Sit down and take a place"] = "Siedersi e prendere posto",
    ["Takes a seat beside you when you sit, and a seat or a spot in your flat at home. Switched off, they stay on their feet beside you."] = "Quando ti siedi, si siede accanto a te, e in casa tua prende un posto o un punto nell’appartamento. Disattivato, resta in piedi accanto a te.",
    ["Comment on fights and loot"] = "Commenta combattimenti e bottino",
    ["Switched off, they say nothing about fights or about what you pick up."] = "Disattivato, non dice nulla su combattimenti o oggetti che raccogli.",
    ["Reply length"] = "Lunghezza della risposta",
    ["Shorter: up to about {words} words"] = "Più breve: fino a circa {words} parole",
    ["Very short: up to about {words} words"] = "Molto breve: fino a circa {words} parole",
    ["A saved choice counts within a few seconds. Clothes change when nobody is looking."] = "Una scelta salvata vale entro pochi secondi. I vestiti cambiano quando nessuno guarda.",
    ["Look and moves"] = "Look e movimenti",
    ["Shift"] = "Maiusc",
    ["Ctrl"] = "Ctrl",
    ["Alt"] = "Alt",
    ["Hold Shift, Ctrl or Alt while you press a key to set a combination such as Shift+F5. A combination runs only with exactly those keys held, and a plain key does not run while one is held. In the game Shift sprints, Ctrl dodges and Alt opens the weapon wheel, so V does that too."] = "Tieni premuto Maiusc, Ctrl o Alt mentre premi un tasto per impostare una combinazione come Maiusc+F5. Una combinazione funziona solo con esattamente quei tasti premuti, e un tasto semplice non funziona finché ne è premuto uno. Nel gioco Maiusc fa correre, Ctrl schivare e Alt apre la ruota delle armi, quindi lo fa anche V.",
    ["Disk space"] = "Spazio su disco",
    ["Your {drive} drive is almost full ({free} GB free). Free space so the mod can save logs and memories."] = "Il disco {drive} è quasi pieno ({free} GB liberi). Liberane un po’, così il mod può salvare log e ricordi.",
    ["An input marked (!) looks like a loopback or virtual input, such as Stereo Mix, CABLE Output or a mixer’s Out. It can carry other apps’ sound, for example the far side of a call, so the mod never picks one by itself."] = "Un ingresso contrassegnato (!) sembra un ingresso loopback o virtuale, come Stereo Mix, CABLE Output o l'uscita di un mixer. Può trasmettere l'audio di altre app, per esempio l'altro capo di una chiamata, quindi il mod non ne sceglie mai uno da solo.",
    ["The input you chose looks like it carries PC sound, not only your voice. If characters hear your calls, choose your real microphone."] = "L'ingresso scelto sembra trasmettere l'audio del PC, non solo la tua voce. Se i personaggi sentono le tue chiamate, scegli il tuo microfono reale.",
    ["{name} looks like it carries PC sound, such as a call, not only your voice. Choose your real microphone in Settings > Voices > Microphone."] = "{name} sembra trasmettere l'audio del PC, come una chiamata, non solo la tua voce. Scegli il tuo microfono reale in Impostazioni > Voci > Microfono.",
    ["No API key is saved yet. Copy your key from your provider, press Paste API key, then test again."] = "Non c'è ancora nessuna chiave API salvata. Copia la tua chiave dal fornitore, premi Incolla chiave API, poi prova di nuovo.",
    ["Add"] = "Aggiungi",
    ["Deletes this free setup: the endpoint URL, the model ID and the API key saved with it."] = "Elimina questa configurazione gratuita: l’URL endpoint, l’ID del modello e la chiave salvata con essa.",
    ["Allow Local AI to use RAM"] = "Consenti a Local AI di usare la RAM",
    ["Off: when the Local AI model you chose does not fit the free graphics memory beside the game, a smaller model that fits is loaded instead, with one notice.\n\nOn: your chosen model is kept and part of it runs from system memory (RAM) on the processor. Replies are slower, and you are told once. It needs enough free RAM, and the game may have less processor time."] = "Disattivato: se il modello Local AI scelto non entra nella memoria video libera accanto al gioco, ne viene caricato uno più piccolo, con una sola notifica.\n\nAttivato: il modello scelto resta e una parte gira dalla memoria di sistema (RAM) sul processore. Le risposte sono più lente e ti viene segnalato una volta. Serve abbastanza RAM libera e il gioco potrebbe avere meno tempo di processore.",
    ["Using {model}"] = "Usa {model}",
    ["{model} is in use because the model you chose did not fit beside the game. Your choice is unchanged."] = "Viene usato {model} perché il modello scelto non entrava accanto al gioco. La tua scelta non cambia.",
    ["Local AI is keeping {model} as you allowed, with part of it in system memory. Replies will be slower."] = "Local AI mantiene {model} come hai consentito, con una parte nella memoria di sistema. Le risposte saranno più lente.",
    ["Choosing Convai or Google Gemini turns it off. Voxtral is not used with it: a voice on Voxtral moves to Pocket and comes back when it is turned off."] = "Scegliere Convai o Google Gemini disattiva questa opzione. Voxtral non viene usato con essa: una voce su Voxtral passa a Pocket e torna quando l’opzione viene disattivata.",
    ["Convai could not sign in. Try again in a moment, or choose Google Gemini or Local AI in Settings > Conversation provider."] = "Impossibile accedere a Convai. Riprova tra un momento oppure scegli Google Gemini o Local AI in Impostazioni > Fornitore di conversazione.",
    ["Convai is answering right now. Your changes reach it as notes sent with each reply, so it may follow them a little less exactly than Google Gemini, Local AI or Custom."] = "Convai sta rispondendo in questo momento. Le tue modifiche gli arrivano come note inviate con ogni risposta, quindi potrebbe seguirle in modo leggermente meno preciso di quanto farebbe con Google Gemini, Local AI o Personalizzato.",
    ["A long edit is shortened for Convai. The rules, memories and speaking style are kept first."] = "Una modifica lunga viene accorciata per Convai. Le regole, i ricordi e lo stile di parola vengono mantenuti per primi.",
    ["Convai: Google Gemini has no key yet"] = "Convai: Google Gemini non ha ancora una chiave",
    ["Copy your Mistral API key first, then press Add. It fills in the endpoint URL and the model ID for Mistral (Ministral 8B) and saves your key from the clipboard. The same key powers the Voxtral cloud voice.\n\nNew Mistral accounts may not get a free API key any more."] = "Copia prima la tua chiave API di Mistral, poi premi Add. Compila l’URL dell’endpoint e l’ID del modello per Mistral (Ministral 8B) e salva la tua chiave dagli appunti. La stessa chiave serve per la voce cloud Voxtral.\n\nI nuovi account Mistral potrebbero non avere più una chiave gratuita.",
    ["Copy your key from Google AI Studio first (aistudio.google.com/apikey, a Google account is enough, no card). It is read from the clipboard once and saved on this computer.\n\nThe free plan has a daily limit of about 500 replies, is not offered in every country, and Google may use free-plan chats to improve its products."] = "Copia prima la tua chiave da Google AI Studio (aistudio.google.com/apikey, basta un account Google, non serve la carta). Viene letta dagli appunti una sola volta e salvata su questo computer.\n\nIl piano gratuito ha un limite giornaliero di circa 500 risposte, non è disponibile in tutti i paesi e Google può usare le chat del piano gratuito per migliorare i suoi prodotti.",
    ["Edit a character’s bio, speaking style, speaking rules and memories, and the prompting for each AI option, or make a character of your own, in your browser.\n\nWorks with every conversation option. With Convai, your changes are sent as notes with each reply. Changes apply from the next reply."] = "Modifica nel tuo browser la biografia, lo stile di parola, le regole di parola e i ricordi di un personaggio, e il prompt di ogni opzione IA, oppure crea un personaggio tuo.\n\nFunziona con ogni opzione di conversazione. Con Convai, le tue modifiche vengono inviate come note con ogni risposta. Le modifiche si applicano dalla prossima risposta.",
    ["Edit characters’ bios, rules and memories, and the prompting for each AI option, in your browser.\n\nWorks with every conversation option. With Convai, your changes are sent as notes with each reply. Changes apply from the next reply."] = "Modifica nel tuo browser le biografie, le regole e i ricordi dei personaggi, e il prompt di ogni opzione IA.\n\nFunziona con ogni opzione di conversazione. Con Convai, le tue modifiche vengono inviate come note con ogni risposta. Le modifiche si applicano dalla prossima risposta.",
    ["From Convai or Google Gemini, turning it on selects Local AI, or Custom when Local AI is not installed. With Local AI it also selects the largest uncensored model that fits. Turning it off restores your choices."] = "Da Convai o Google Gemini, attivandolo seleziona Local AI, oppure Personalizzato se Local AI non è installata. Con Local AI seleziona anche il modello senza censure più grande che entra. Disattivandolo si ripristinano le tue scelte.",
    ["Google Gemini (free plan)"] = "Google Gemini (piano gratuito)",
    ["Google Gemini API key"] = "Chiave API di Google Gemini",
    ["Google Gemini has no key yet, so Convai is used. Add your key in Settings > Conversation provider."] = "Google Gemini non ha ancora una chiave, quindi viene usato Convai. Aggiungi la tua chiave in Impostazioni > Fornitore di conversazione.",
    ["Google Gemini replies are spoken by a local voice instead of the Convai cloud voice."] = "Le risposte di Google Gemini sono pronunciate da una voce locale invece che dalla voce cloud di Convai.",
    ["Google Gemini: key not accepted"] = "Google Gemini: chiave non accettata",
    ["The service is not available in your region."] = "Il servizio non è disponibile nella tua regione.",
    ["Google accepted the key."] = "Google ha accettato la chiave.",
    ["Google did not accept this key. Check it in Google AI Studio, then Remove it and Add the right one."] = "Google non ha accettato questa chiave. Controllala in Google AI Studio, poi premi Rimuovi e aggiungi quella giusta con Aggiungi.",
    ["Google accepted the key, but the free allowance is used up for now."] = "Google ha accettato la chiave, ma il piano gratuito è esaurito per ora.",
    ["The key is saved, but Google Gemini is not available in your region."] = "La chiave è salvata, ma Google Gemini non è disponibile nella tua regione.",
    ["The key is saved, but Google could not be reached to check it."] = "La chiave è salvata, ma non è stato possibile contattare Google per verificarla.",
    ["Google Gemini: rate limited for a minute"] = "Google Gemini: limitato per un minuto",
    ["Google Gemini: free allowance used up for today"] = "Google Gemini: piano gratuito esaurito per oggi",
    ["Google Gemini: not available in your region"] = "Google Gemini: non disponibile nella tua regione",
    ["Google did not accept your Gemini key. Check it in Google AI Studio and add it again."] = "Google non accetta la chiave Gemini. Controllala in Google AI Studio e riaggiungila.",
    ["Your free Gemini allowance for today is used up. It resets at {time}. Use Convai or Local AI."] = "Il tuo piano gratuito Gemini di oggi è esaurito. Si ripristina alle {time}. Usa Convai o Local AI.",
    ["Your free Gemini allowance for today is used up. It resets tomorrow. Use Convai or Local AI."] = "Il tuo piano gratuito Gemini di oggi è esaurito. Si ripristina domani. Usa Convai o Local AI.",
    ["Google Gemini is rate limiting you. Wait a minute, then try again."] = "Google Gemini ti sta limitando. Attendi un minuto, poi riprova.",
    ["Google Gemini is not available in your region. Use Convai or Local AI."] = "Google Gemini non è disponibile nella tua regione. Usa Convai o Local AI.",
    ["Google Gemini is busy or had an error. Wait a minute, then try again."] = "Google Gemini è occupato o ha avuto un errore. Attendi un minuto, poi riprova.",
    ["Google Gemini could not be reached. Check your internet connection, then try again."] = "Impossibile raggiungere Google Gemini. Controlla la connessione, poi riprova.",
    ["The Gemini model is not available right now. Try again later or use Local AI."] = "Il modello Gemini non è disponibile ora. Riprova più tardi o usa Local AI.",
    ["Google Gemini: model unavailable"] = "Google Gemini: modello non disponibile",
    ["Mistral (your key)"] = "Mistral (la tua chiave)",
    ["Requires a Mistral key (add it with the Mistral preset on the Custom endpoint page)"] = "Richiede una chiave Mistral (aggiungila con il preset Mistral nella pagina Custom endpoint)",
    ["The conversation limit has been reached. Try again later, or choose Local AI or Google Gemini in Settings > Conversation provider."] = "È stato raggiunto il limite di conversazioni. Riprova più tardi oppure scegli Local AI o Google Gemini in Impostazioni > Fornitore di conversazione.",
    ["The longest reply, in words. Works with Google Gemini, Local AI and Custom, not Convai."] = "La risposta più lunga, in parole. Funziona con Google Gemini, Local AI e Custom, non con Convai.",
    ["They join as a copy of the model they were made from. They talk with Google Gemini, Local AI or Custom; with Convai they talk as an ordinary person."] = "Si unisce come una copia del modello da cui è stato creato. Parla con Google Gemini, Local AI o Personalizzato; con Convai parla come una persona normale.",
    ["Today’s Convai turns are used.\nIt resets at {time}. Try Local AI (unlimited) or Google Gemini (your own key)."] = "Turni Convai di oggi esauriti.\nSi ripristina alle {time}. Usa Local AI (illimitata) o Google Gemini (la tua chiave).",
    ["Today’s Convai turns are used.\nTry Local AI (unlimited) or Google Gemini (your own key)."] = "Turni Convai di oggi esauriti.\nUsa Local AI (illimitata) o Google Gemini (la tua chiave).",
    ["Today’s {limit} Convai turns are used.\nIt resets at {time}. Try Local AI (unlimited) or Google Gemini (your own key)."] = "Oggi {limit} turni Convai usati.\nSi ripristina alle {time}. Usa Local AI (illimitata) o Google Gemini (la tua chiave).",
    ["Today’s {limit} Convai turns are used.\nTry Local AI (unlimited) or Google Gemini (your own key)."] = "Oggi {limit} turni Convai usati.\nUsa Local AI (illimitata) o Google Gemini (la tua chiave).",
    ["Turns the content pack {name} on or off. A pack changes how the characters talk. Its prompt changes work with Google Gemini, Local AI and Custom. On Convai its world rules and its own Convai characters apply. A switch counts from the next reply, new names after a restart."] = "Attiva o disattiva il pacchetto di contenuti {name}. Un pacchetto cambia il modo in cui parlano i personaggi. Le sue modifiche al prompt funzionano con Google Gemini, Local AI e Personalizzato. Su Convai si applicano le sue regole del mondo e i suoi personaggi Convai. Un cambio vale dalla risposta successiva, i nomi nuovi dopo un riavvio.",
    ["What the game tells each character about this moment. A character mentions it only when it fits the talk.\n\nAn off kind is left out of every conversation provider (Convai, Google Gemini, Local AI and Custom)."] = "Ciò che il gioco comunica a ogni personaggio su questo momento. Un personaggio ne parla solo quando si adatta alla conversazione.\n\nUn’info disattivata viene esclusa da tutti i fornitori di conversazione (Convai, Google Gemini, Local AI e Personalizzato).",
    ["Who writes your companions’ replies. A change waits until no conversation is running.\n\nConvai free tier needs no setup and gives better replies. Convai API key uses your own key. Google Gemini uses your own free key, and its memory stays on this computer.\n\nWith Google Gemini, Local AI or Custom, Convai’s cloud voice is replaced by a local voice. Speech is recognized on this computer, so the voice key works."] = "Chi scrive le risposte dei tuoi compagni. Una modifica attende che nessuna conversazione sia in corso.\n\nIl piano gratuito di Convai non richiede configurazione e offre risposte migliori. La chiave API di Convai usa la tua chiave. Google Gemini usa la tua chiave gratuita e la memoria resta su questo computer.\n\nCon Google Gemini, Local AI o Personalizzato, la voce cloud di Convai viene sostituita da una voce locale. Il riconoscimento vocale avviene su questo computer, quindi il tasto vocale funziona.",
    ["Who writes your companions’ replies. A change waits until no conversation is running.\n\nConvai free tier needs no setup and gives better replies. Convai API key uses your own key. Google Gemini uses your own free key, and its memory stays on this computer.\n\nWith Google Gemini, Local AI or Custom, Convai’s cloud voice is replaced by a local voice. Speech recognition for the voice key is not available yet with them, so type your messages."] = "Chi scrive le risposte dei tuoi compagni. Una modifica attende che nessuna conversazione sia in corso.\n\nIl piano gratuito di Convai non richiede configurazione e offre risposte migliori. La chiave API di Convai usa la tua chiave. Google Gemini usa la tua chiave gratuita e la memoria resta su questo computer.\n\nCon Google Gemini, Local AI o Personalizzato, la voce cloud di Convai viene sostituita da una voce locale. Il riconoscimento vocale per il tasto vocale non è ancora disponibile con questi, quindi scrivi i tuoi messaggi.",
    ["You have used today’s {limit} turns, which come back at {time}. To keep talking now, choose Local AI (unlimited) or Google Gemini (with your own key)."] = "Hai usato i tuoi {limit} turni di oggi. Tornano alle {time}. Per continuare subito, scegli Local AI (nessun limite) oppure Google Gemini (con la tua chiave).",
    ["Your changes work with every conversation option. With Convai they are sent as notes with each reply."] = "Le tue modifiche funzionano con ogni opzione di conversazione. Con Convai vengono inviate come note con ogni risposta.",
    ["Your own characters talk only with Google Gemini, Local AI or Custom. With Convai they speak as an ordinary person."] = "I tuoi personaggi parlano solo con Google Gemini, Local AI o Personalizzato. Con Convai parlano come una persona normale.",
    ["{name} is one of your own characters. They need Google Gemini, Local AI or Custom, so with Convai they talk as an ordinary person."] = "{name} è uno dei tuoi personaggi. Ha bisogno di Google Gemini, Local AI o Personalizzato, quindi con Convai parla come una persona normale.",
    ["{name} is one of your own characters. They need Google Gemini, Local AI or Custom: choose one under Conversation provider in the settings."] = "{name} è uno dei tuoi personaggi. Ha bisogno di Google Gemini, Local AI o Custom: scegline uno in Fornitore di conversazione nelle impostazioni.",
    ["This character needs Google Gemini, Local AI or Custom to answer."] = "Questo personaggio ha bisogno di Google Gemini, Local AI o Personalizzato per rispondere.",
    ["You’ve reached today’s Convai free tier limit. It resets at {time}. To keep talking now, choose another provider in Settings > Conversation provider. Local AI is unlimited and runs on your PC. Google Gemini works with your own key."] = "Hai raggiunto il limite giornaliero di Convai (piano gratuito). Si ripristina alle {time}. Per continuare subito, scegli un altro fornitore in Impostazioni > Fornitore di conversazione. Local AI è illimitata e funziona sul tuo PC. Google Gemini funziona con la tua chiave.",
    ["Character bonds"] = "Legami con i personaggi",
    ["Every named character has a bond with you, level 1 to 10. Quests finished together, a romance, eddies paid back and talking raise it; threats and insults lower it. Closer characters trust you more.\n\nA notice shows each level change. Forget clears the talk part. Off by default."] = "Ogni personaggio ha un legame con te, dal livello 1 al 10. Cresce con le missioni completate insieme, una relazione, gli eddies restituiti e le chiacchiere; minacce e insulti lo abbassano. I personaggi più vicini si fidano di più di te.\n\nUn avviso segnala ogni cambio di livello. Dimentica cancella la parte delle chiacchiere. Disattivato di default.",
    ["Bond with {name}: level {level}, {title}"] = "Legame con {name}: livello {level}, {title}",
    ["Bond with {name} fell: level {level}, {title}"] = "Legame con {name} sceso: livello {level}, {title}",
    ["Acquaintance"] = "Conoscente",
    ["Familiar face"] = "Volto noto",
    ["Friendly"] = "Amichevole",
    ["Friend"] = "Amico",
    ["Good friend"] = "Buon amico",
    ["Close friend"] = "Amico stretto",
    ["Trusted"] = "Fidato",
    ["Confidant"] = "Confidente",
    ["Family"] = "Famiglia",
    ["Ride or die"] = "Fedelissimo",
    ["Story packs"] = "Pacchetti di storia",
    ["When you are close and a character’s own quests are done, they can start a short story of their own. It plays out in talks, texts and calls, and some use Eddies with characters and Immersive invitations.\n\nNeeds Character bonds. Own characters and channels only, never the game’s own scenes or quests. Off by default."] = "Quando sei vicino a un personaggio e le sue missioni sono finite, può iniziare una breve storia tutta sua. Si svolge in chiacchierate, messaggi e chiamate, e alcune usano Eddies con i personaggi e Inviti immersivi.\n\nRichiede Legami con i personaggi. Solo i tuoi personaggi e canali, mai scene o missioni del gioco. Disattivato di default.",
    ["Characters text first"] = "I personaggi scrivono per primi",
    ["Bond: level {level}, {title}"] = "Legame: livello {level}, {title}",
    ["Story: {title}"] = "Storia: {title}",
    ["Bonds are not kept while Character bonds is off, so nobody is listed here. Turn it on in Settings, under Companions."] = "I legami non vengono tenuti finché Legami con i personaggi è disattivato, quindi qui non c’è nessuno. Attivalo in Impostazioni, sotto Compagni.",
    ["Character bonds are off"] = "Legami con i personaggi è disattivato",
    ["From their story: {story}, from talking: {talk}"] = "Dalla loro storia: {story}, dalle conversazioni: {talk}",
    ["Highest level"] = "Livello massimo",
    ["Hurt: {points}"] = "Ferito: {points}",
    ["Hurt: {points}, gone in about a game day"] = "Ferito: {points}, passerà in circa un giorno di gioco",
    ["Hurt: {points}, gone in about {days} game days"] = "Ferito: {points}, passerà in circa {days} giorni di gioco",
    ["Last talked: today"] = "Ultima conversazione: oggi",
    ["Last talked: yesterday"] = "Ultima conversazione: ieri",
    ["Last talked: {days} days ago"] = "Ultima conversazione: {days} giorni fa",
    ["Level {level}"] = "Livello {level}",
    ["No story yet"] = "Ancora nessuna storia",
    ["Nobody yet"] = "Ancora nessuno",
    ["See the characters you have talked to and how close each one is to you: the bond level, what raised or hurt it, their quests and the stories they are in."] = "Guarda i personaggi con cui hai parlato e quanto ti è vicino ciascuno: il livello del legame, cosa l’ha fatto salire o l’ha incrinato, le loro missioni e le storie in cui si trovano.",
    ["Talk to a character and your bond with them shows here."] = "Parla con un personaggio e il tuo legame con lui compare qui.",
    ["The characters you have talked to and how close each one is to you. The most recent come first."] = "I personaggi con cui hai parlato e quanto ti è vicino ciascuno. I più recenti vengono per primi.",
    ["Their quests: {done} of {total} finished"] = "Le loro missioni: {done} su {total} completate",
    ["Warmth: {points}"] = "Calore: {points}",
    ["{points} of {needed} points to level {to}"] = "{points} su {needed} punti per il livello {to}",
    ["{title} (finished)"] = "{title} (conclusa)",
    ["{title}: {label}"] = "{title}: {label}",
    ["Characters you are close to can text or call you first now and then, and Johnny can speak up in your head. It only happens at calm moments, never in a fight, a scene or a call, and only a few times a day.\n\nNeeds Story packs. Own characters and channels only. Off by default."] = "I personaggi a cui sei vicino possono scriverti o chiamarti per primi ogni tanto, e Johnny può farsi sentire nella tua testa. Succede solo nei momenti tranquilli, mai durante uno scontro, una scena o una chiamata, e solo poche volte al giorno.\n\nRichiede Pacchetti di storia. Solo i tuoi personaggi e canali. Disattivato di default.",
    ["Puts every setting on Settings, Romantic relationships, Dynamic info and Key bindings back to its default. Press the button twice to confirm."] = "Riporta ogni impostazione di Impostazioni, Relazioni romantiche, Info in tempo reale e Assegnazione tasti al valore predefinito. Premi il pulsante due volte per confermare.",
    ["Romantic relationships"] = "Relazioni romantiche",
    ["Add a key first"] = "Aggiungi prima una chiave",
    ["Add a key to choose it"] = "Aggiungi una chiave per sceglierla",
    ["Asks Inworld whether your saved key is accepted. It costs nothing and no speech is made."] = "Chiede a Inworld se la tua chiave salvata è accettata. Non costa nulla e non viene generato alcun parlato.",
    ["Chosen as the Companion voice"] = "Scelta come voce del compagno",
    ["Connected"] = "Connesso",
    ["Deletes the saved key. If Inworld is your Companion voice, replies show as text until you add a key again."] = "Elimina la chiave salvata. Se Inworld è la tua voce dei compagni, le risposte vengono mostrate come testo finché non aggiungi di nuovo una chiave.",
    ["Inworld API key"] = "Chiave API di Inworld",
    ["Inworld cloud voice"] = "Voce cloud Inworld",
    ["Inworld did not accept that key."] = "Inworld non ha accettato quella chiave.",
    ["Inworld is not used with Mature content."] = "Inworld non viene usato con i Contenuti per adulti.",
    ["Inworld voice"] = "Voce Inworld",
    ["Inworld · Cloud voice"] = "Inworld · Voce cloud",
    ["Inworld · needs key"] = "Inworld · serve chiave",
    ["Inworld · not with Mature"] = "Inworld · non con 18+",
    ["Key refused"] = "Chiave rifiutata",
    ["Needs your own Inworld key, from inworld.ai. Inworld’s free plan is a one-time trial of about 70 minutes of speech, then you pay as you go.\n\nCopy your key first, then press Add. It is read from the clipboard once, checked with Inworld and saved on this computer."] = "Ti serve una tua chiave Inworld, da inworld.ai. Il piano gratuito di Inworld è una prova una tantum di circa 70 minuti di voce, poi paghi in base all’uso.\n\nCopia prima la chiave, poi premi Aggiungi. Viene letta dagli appunti una sola volta, verificata da Inworld e salvata su questo computer.",
    ["Not reachable"] = "Non raggiungibile",
    ["Not used with Mature content"] = "Non usato con i Contenuti per adulti",
    ["Ready to choose in Companion voices"] = "Pronta da scegliere in Voci dei compagni",
    ["Requires an Inworld key (add it in Settings > Voices > Custom voices)"] = "Richiede una chiave Inworld (aggiungila in Impostazioni > Voci > Voci personalizzate)",
    ["Speaks each companion in their own voice, on your own Inworld key. Works in English and the other languages Inworld supports. Choose it under Companion voices, where it is listed last once a key is added."] = "Parla con la voce di ogni compagno, usando la tua chiave Inworld. Funziona in inglese e nelle altre lingue supportate da Inworld. Scegli la voce in Voci dei compagni, dove compare per ultima quando aggiungi una chiave.",
    ["{voice} · needs Inworld key"] = "{voice} · richiede la chiave API di Inworld",
    ["Choose a character to start editing."] = "Scegli un personaggio per iniziare a modificarlo.",
    ["Clear search"] = "Cancella ricerca",
    ["Companion"] = "Compagno",
    ["Companions"] = "Compagni",
    ["Custom voice"] = "Voce personalizzata",
    ["Close"] = "Chiudi",
    ["In front of you"] = "Di fronte a te",
    ["You have switched off as many people as the editor keeps ({max}). Switch one back on first."] = "Hai disattivato tante persone quante ne conserva l'editor ({max}). Riattivane una prima.",
    ["That person cannot be switched off."] = "Questa persona non può essere disattivata.",
    ["Don’t talk to this character"] = "Non parlare con questo personaggio",
    ["While this is on, they do not answer you and never join a group chat. Untick it to talk to them again."] = "Mentre è attivo, non ti rispondono e non partecipano mai a una chat di gruppo. Disattivalo per parlarci di nuovo.",
    ["Switched off."] = "Disattivato.",
    ["Switched back on."] = "Riattivato.",
    ["Switch back on"] = "Riattiva",
    ["Don’t talk to this person"] = "Non parlare con questa persona",
    ["It also stops everyone the game builds from the same record, so other people of the same kind may stop answering too."] = "Arresta anche tutti coloro che il gioco costruisce dallo stesso record, quindi altre persone dello stesso tipo potrebbero smettere di rispondere.",
    ["Switched off"] = "Disattivato",
    ["People and characters you chose not to talk to. Switch one back on to talk to them again."] = "Persone e personaggi con cui hai scelto di non parlare. Riattivane uno per parlarci di nuovo.",
    ["Recently edited"] = "Modificati di recente",
    ["Romance"] = "Romance",
    ["Romances"] = "Romanze",
    ["Side character"] = "Personaggio secondario",
    ["Side characters"] = "Personaggi secondari",
    ["Minor character"] = "Personaggio minore",
    ["Minor characters"] = "Personaggi minori",
    ["Story"] = "Storia",
    ["Story character"] = "Personaggio della storia",
    ["Unsaved changes"] = "Modifiche non salvate",
    ["Together"] = "Insieme",
    ["You and {name} are together. This grew from talking and is kept in this save. To end it, tell them."] = "Tu e {name} siete insieme. Questo è nato dalle conversazioni e è salvato in questo salvataggio. Per terminarlo, dillo.",
    ["A gang you keep killing may rarely send a small squad after you, with a short threat to shout. A long wait follows each one.\n\nNever in a fight, scene, call, vehicle, indoors, safe zone or while wanted."] = "Una banda che continui a uccidere può mandarti, di rado, una piccola squadra con una breve minaccia. Ognuna è seguita da una lunga attesa.\n\nMai durante scontri, scene, chiamate, a bordo di un veicolo, al chiuso, in zone sicure o mentre sei ricercato.",
    ["A nearby companion comments as combat starts and ends, and after you collect loot from the world. Storage transfers stay silent.\n\nCooldowns: ten minutes after a fight and between ordinary loot comments, two minutes for new Legendary gear. Pickups during a fight become one comment at its end. Conversations and story scenes come first. Loading a save resets the cooldowns."] = "Un compagno vicino commenta a inizio e fine combattimento e dopo aver raccolto bottino. I trasferimenti nel deposito restano muti.\n\nAttese: dieci minuti dopo uno scontro e tra i commenti sul bottino normali, due minuti per l'equipaggiamento leggendario nuovo. Il bottino preso in combattimento diventa un commento alla fine. Conversazioni e scene hanno la precedenza. Caricare un salvataggio azzera le attese.",
    ["AI provider"] = "Fornitore di IA",
    ["Choose how V’s voice is used."] = "Scegli come usare la voce di V.",
    ["Companion vision"] = "Visione dei compagni",
    ["Companion voice volume (%)"] = "Volume della voce dei compagni (%)",
    ["Companions react"] = "I compagni reagiscono",
    ["Each line also comes with vision: a recent view of your surroundings, taken from the game window just before you talk. Works with every conversation provider. Local AI needs a model with vision. A model without it just gets your words.\n\nOnly the game window, only while someone is near, kept briefly in memory. Off means nothing is captured."] = "Ogni battuta viene con visione: un'immagine recente dei tuoi dintorni, presa dalla finestra del gioco. Funziona con ogni fornitore di chat. Local AI richiede un modello con visione, altrimenti riceve solo le tue parole.\n\nSolo la finestra del gioco, solo con qualcuno vicino, in memoria brevemente. Disattivato, non si cattura nulla.",
    ["Error reports, developer mode and help."] = "Segnalazioni errori, modalità sviluppatore e aiuto.",
    ["How everyone sounds, and how you talk."] = "Come suona tutto il mondo, e come parli tu.",
    ["How the world reacts to V."] = "Come il mondo reagisce a V.",
    ["Life with your party."] = "Vita con il tuo gruppo.",
    ["Night City"] = "Night City",
    ["Off: V is silent.\n\nTyped lines: the lines you type are spoken out loud too, in the V voice that matches yours, then the companion answers.\n\nTyped and spoken lines: what you say by microphone (hold to talk or Voice activation) is also spoken by V, and the reply follows V’s line.\n\nV’s line is always waited for, up to about 30 s without audio. The next row picks the voice engine."] = "Disattivato: V sta zitto.\n\nBattute scritte: quello che scrivi viene detto anche ad alta voce, con la voce di V che corrisponde alla tua, poi risponde il compagno.\n\nBattute scritte e parlate: quello che dici al microfono (tieni premuto per parlare o Attivazione vocale) viene detto anche da V, e la risposta viene dopo.\n\nLa battuta di V si attende sempre (fino a 30 s senza audio). La riga successiva sceglie il motore.",
    ["Privacy and help"] = "Privacy e aiuto",
    ["Return to the settings categories."] = "Torna alle categorie di impostazioni.",
    ["Return to {page}."] = "Torna a {page}.",
    ["The language of the menus and how subtitles look."] = "La lingua dei menu e l'aspetto dei sottotitoli.",
    ["The voice V speaks with, whatever the companions use. It counts only while V’s voice is not Off.\n\nPocket: on your processor, about 0.2 s (its own small model if the companions use another voice). Voxtral: cloud, with your Mistral key. OmniVoice: the companions’ GPU voice, a second more wait."] = "La voce con cui parla V, qualunque sia quella dei compagni. Conta solo quando la voce di V non è Disattivata.\n\nPocket: sul processore, circa 0,2 s (con un proprio piccolo modello se i compagni usano un'altra voce). Voxtral: nel cloud, con la tua chiave Mistral. OmniVoice: la voce GPU dei compagni, un secondo in più.",
    ["The yellow border is Windows showing a capture. Turn off Companion vision to stop it."] = "Il bordo giallo è Windows che mostra una cattura. Disattiva Visione dei compagni.",
    ["This Local AI model has no vision, so replies use only your words."] = "Questo modello di Local AI non ha visione, quindi le risposte usano solo le tue parole.",
    ["This model has vision with its vision file, from {folder}/vision on Hugging Face."] = "Questo modello ha visione con il suo file vision, da {folder}/vision su Hugging Face.",
    ["Typed and spoken lines"] = "Battute scritte e parlate",
    ["Typed lines"] = "Battute scritte",
    ["Voice AI and microphone"] = "IA vocale e microfono",
    ["V’s voice engine"] = "Motore vocale di V",
    ["Where V is: the district, and V’s apartment or the named place when the game says so.\n\nOff: characters are not told where you are, and the mod stops reading it from the game. The vision Convai has of what V sees, and an add-on’s own text, are not affected."] = "Dove si trova V: il distretto e l'appartamento di V o il luogo con nome, quando il gioco lo indica.\n\nDisattivato: ai personaggi non viene detto dove ti trovi, e il mod smette di leggerlo dal gioco. La visione che Convai riceve di quello che vede V, e il testo proprio di un add-on, restano invariati.",
    ["Who writes the replies."] = "Chi scrive le risposte.",
    ["Who you can talk to and what they know."] = "Con chi puoi parlare e cosa sanno.",
    ["Your AMD Radeon card can run OmniVoice. Set it up in Settings > Voice AI and microphone > OmniVoice for AMD: one download, then it starts by itself. Until then Pocket speaks."] = "La tua scheda AMD Radeon può far girare OmniVoice. Configuralo in Impostazioni > IA vocale e microfono > OmniVoice per AMD: un download, poi parte da solo. Fino ad allora parla Pocket.",
    ["Your Custom endpoint does not accept vision, so replies use only your words."] = "Il tuo endpoint Custom non accetta visione, quindi le risposte usano solo le tue parole.",
    ["Type a name to search"] = "Scrivi un nome da cercare",
    ["In person"] = "Di persona",
    ["Phone calls and texts"] = "Chiamate e messaggi",
    ["The same switches for a character V is only calling or texting: holocalls and Phone Chat. A companion standing beside V is still treated as in person, even when V uses the phone."] = "Gli stessi interruttori valgono per un personaggio con cui V parla solo al telefono o per messaggi: olochiamate e Chat del telefono. Un compagno in piedi accanto a V viene comunque considerato di persona, anche quando V usa il telefono.",
}
